calc.mjs.text:
// Crypto cost-basis lot matcher. Pure functions, no I/O, no dependencies.
//
// Input is a CSV of the user's own transactions. Every row is a buy, an income
// receipt, a sale/spend, or a transfer (ignored). A coin-for-coin swap is entered
// as two rows: a sale of what was given up and a buy of what was received, each at
// its USD value that day. The module matches each disposal to earlier acquisition
// lots under FIFO, LIFO, HIFO, LOFO or a tax-aware greedy rule, splits every
// disposal into Form 8949-style rows with short/long-term holding periods, and
// compares the methods on the chosen tax year. It prices nothing and fetches
// nothing: every figure comes from the rows the user supplies.

export const METHODS = ["FIFO", "LIFO", "HIFO", "LOFO", "TAXMIN"];
export const METHOD_LABELS = {
  FIFO: "First in, first out",
  LIFO: "Last in, first out",
  HIFO: "Highest cost first",
  LOFO: "Lowest cost first",
  TAXMIN: "Tax-aware greedy (lowest tax per coin first)",
};

const EPS = 1e-9;
const cents = (n) => Math.round((n + Number.EPSILON * Math.sign(n)) * 100) / 100;

// ---- CSV ---------------------------------------------------------------

export function parseCsv(text) {
  const src = String(text ?? "").replace(/^﻿/, "");
  const firstLine = src.split(/\r?\n/, 1)[0] || "";
  const delim = firstLine.includes("\t") && !firstLine.includes(",") ? "\t" : ",";
  const rows = [];
  let row = [];
  let cell = "";
  let quoted = false;
  for (let i = 0; i < src.length; i++) {
    const c = src[i];
    if (quoted) {
      if (c === '"') {
        if (src[i + 1] === '"') { cell += '"'; i++; } else quoted = false;
      } else cell += c;
    } else if (c === '"') quoted = true;
    else if (c === delim) { row.push(cell); cell = ""; }
    else if (c === "\n" || c === "\r") {
      if (c === "\r" && src[i + 1] === "\n") i++;
      row.push(cell); cell = "";
      if (row.some((x) => x.trim() !== "")) rows.push(row);
      row = [];
    } else cell += c;
  }
  row.push(cell);
  if (row.some((x) => x.trim() !== "")) rows.push(row);
  return rows.map((r) => r.map((x) => x.trim()));
}

const norm = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();

const HEADER_ALIASES = {
  date: ["date", "time", "timestamp", "datetime", "date utc", "transaction date", "date time", "date and time"],
  type: ["type", "side", "transaction type", "operation", "action", "kind"],
  asset: ["asset", "currency", "coin", "symbol", "token", "ticker", "base asset"],
  quantity: ["quantity", "amount", "qty", "size", "quantity transacted", "units"],
  total: ["total", "total usd", "usd value", "value", "value usd", "proceeds", "subtotal", "total value", "usd"],
  price: ["price", "price per unit", "spot price", "unit price", "price usd", "rate"],
  fee: ["fee", "fees", "fee usd", "fees usd", "commission"],
  wallet: ["wallet", "account", "exchange", "platform", "source"],
  reported: ["reported", "broker reported", "1099-da", "form 1099-da", "reported on 1099-da"],
  toAsset: ["to asset", "received asset", "asset received", "buy asset", "to coin", "to currency"],
  toQuantity: ["to quantity", "received quantity", "quantity received", "buy quantity", "to amount", "received amount"],
  toWallet: ["to wallet", "to account", "to", "destination", "destination wallet", "to exchange"],
};

export function mapHeaders(headerRow) {
  const map = {};
  const names = headerRow.map(norm);
  for (const [field, aliases] of Object.entries(HEADER_ALIASES)) {
    for (const a of aliases) {
      const idx = names.indexOf(a);
      if (idx >= 0) { map[field] = idx; break; }
    }
  }
  return map;
}

const TYPE_WORDS = {
  buy: ["buy", "purchase", "bought", "advanced trade buy", "market buy", "limit buy"],
  income: ["income", "reward", "rewards", "staking", "staking reward", "airdrop", "mining", "interest", "earn", "learning reward", "referral", "payment received"],
  sell: ["sell", "sale", "sold", "spend", "market sell", "limit sell", "advanced trade sell", "payment sent", "convert out"],
  swap: ["swap", "trade", "exchange", "convert", "dex swap", "token swap"],
  transfer: ["transfer", "send", "receive", "deposit", "withdrawal", "withdraw", "move"],
};

export function normalizeType(raw) {
  const t = norm(raw);
  for (const [kind, words] of Object.entries(TYPE_WORDS)) if (words.includes(t)) return kind;
  return null;
}

export function parseDate(raw) {
  const s = String(raw ?? "").trim();
  let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T\s].*)?$/);
  let y, mo, d;
  if (m) { y = +m[1]; mo = +m[2]; d = +m[3]; }
  else {
    m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:[T\s].*)?$/);
    if (!m) return null;
    mo = +m[1]; d = +m[2]; y = +m[3];
  }
  const dt = new Date(Date.UTC(y, mo - 1, d));
  if (dt.getUTCFullYear() !== y || dt.getUTCMonth() !== mo - 1 || dt.getUTCDate() !== d) return null;
  return dt.toISOString().slice(0, 10);
}

function parseNumber(raw) {
  if (raw === undefined || raw === null) return null;
  const s = String(raw).replace(/[$,\s]/g, "").replace(/^\((.*)\)$/, "-$1");
  if (s === "") return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : NaN;
}

// Whether the broker reported a sale on Form 1099-DA: "basis" (reported with
// cost basis), "nobasis" (reported, basis not) or "" (not reported). undefined
// means the cell held something else.
function parseReported(raw) {
  const t = norm(raw).replace(/[\s_-]+/g, "");
  if (t === "") return "";
  if (["basis", "withbasis", "yes"].includes(t)) return "basis";
  if (["nobasis", "basisnotreported"].includes(t)) return "nobasis";
  if (["none", "no", "notreported", "n", "0"].includes(t)) return "";
  return undefined;
}

// ---- rows --------------------------------------------------------------

// Returns { transactions, skipped, errors }. A transaction is
// { line, date, kind: 'buy'|'income'|'sell', asset, qty, usd, fee, wallet }.
export function parseTransactions(text) {
  const grid = parseCsv(text);
  const out = { transactions: [], skipped: [], errors: [] };
  if (grid.length === 0) return out;
  const map = mapHeaders(grid[0]);
  const missing = ["date", "type", "asset", "quantity"].filter((f) => map[f] === undefined);
  if (map.total === undefined && map.price === undefined) missing.push("total or price");
  if (missing.length) {
    out.errors.push(`Header row is missing: ${missing.join(", ")}. Expected columns like date, type, asset, quantity, total (USD), fee, wallet.`);
    return out;
  }
  for (let i = 1; i < grid.length; i++) {
    const r = grid[i];
    const line = i + 1;
    const get = (f) => (map[f] === undefined ? "" : (r[map[f]] ?? ""));
    const kind = normalizeType(get("type"));
    if (kind === null) { out.errors.push(`Line ${line}: unrecognised type "${get("type")}" (use buy, sell, income or transfer).`); continue; }
    const toWallet = map.toWallet === undefined ? "" : (r[map.toWallet] ?? "");
    if (kind === "swap") {
      // A coin-for-coin swap is a sale of the coin given up and a buy of the coin received,
      // both at the USD value you give for the swap.
      const date = parseDate(get("date"));
      if (!date) { out.errors.push(`Line ${line}: unreadable date "${get("date")}" (use YYYY-MM-DD or MM/DD/YYYY).`); continue; }
      const asset = get("asset").toUpperCase();
      const toAsset = map.toAsset === undefined ? "" : (r[map.toAsset] ?? "").toUpperCase();
      const qty = Math.abs(parseNumber(get("quantity")));
      const toQty = map.toQuantity === undefined ? NaN : Math.abs(parseNumber(r[map.toQuantity]));
      if (!asset || !toAsset) { out.errors.push(`Line ${line}: a swap needs the coin given up (asset) and the coin received (to asset).`); continue; }
      if (asset === toAsset) { out.errors.push(`Line ${line}: a swap needs two different coins.`); continue; }
      if (!(qty > 0) || !(toQty > 0)) { out.errors.push(`Line ${line}: a swap needs a positive quantity and to quantity.`); continue; }
      const totalRaw = map.total === undefined ? null : parseNumber(get("total"));
      const priceRaw = map.price === undefined ? null : parseNumber(get("price"));
      let usd = totalRaw !== null && !Number.isNaN(totalRaw) ? Math.abs(totalRaw) : null;
      if (usd === null && priceRaw !== null && !Number.isNaN(priceRaw)) usd = Math.abs(priceRaw) * qty;
      if (usd === null) { out.errors.push(`Line ${line}: a swap needs the USD value of the swap (total) on that day.`); continue; }
      const feeRaw = map.fee === undefined ? 0 : parseNumber(get("fee"));
      const fee = Number.isNaN(feeRaw) || feeRaw === null ? 0 : Math.abs(feeRaw);
      const wallet = get("wallet") || "";
      out.transactions.push({ line, date, kind: "sell", asset, qty, usd, fee, wallet, swap: true });
      out.transactions.push({ line, date, kind: "buy", asset: toAsset, qty: toQty, usd, fee: 0, wallet, swap: true });
      continue;
    }
    if (kind === "transfer" && !toWallet) { out.skipped.push(`Line ${line}: transfer ignored (not a taxable event; add a "to wallet" column to move its lots in per-wallet mode).`); continue; }
    const date = parseDate(get("date"));
    if (!date) { out.errors.push(`Line ${line}: unreadable date "${get("date")}" (use YYYY-MM-DD or MM/DD/YYYY).`); continue; }
    const asset = get("asset").toUpperCase();
    if (!asset) { out.errors.push(`Line ${line}: missing asset.`); continue; }
    const qty = Math.abs(parseNumber(get("quantity")));
    if (!(qty > 0)) { out.errors.push(`Line ${line}: quantity must be a positive number.`); continue; }
    if (kind === "transfer") {
      const from = get("wallet");
      if (!from) { out.errors.push(`Line ${line}: a transfer needs a wallet to move the coins out of.`); continue; }
      if (from === toWallet) { out.skipped.push(`Line ${line}: transfer from and to the same wallet ignored.`); continue; }
      out.transactions.push({ line, date, kind, asset, qty, usd: 0, fee: 0, wallet: from, toWallet });
      continue;
    }
    const totalRaw = map.total === undefined ? null : parseNumber(get("total"));
    const priceRaw = map.price === undefined ? null : parseNumber(get("price"));
    let usd = totalRaw !== null && !Number.isNaN(totalRaw) ? Math.abs(totalRaw) : null;
    if (usd === null && priceRaw !== null && !Number.isNaN(priceRaw)) usd = Math.abs(priceRaw) * qty;
    if (usd === null) { out.errors.push(`Line ${line}: no USD total or price.`); continue; }
    const feeRaw = map.fee === undefined ? 0 : parseNumber(get("fee"));
    const fee = Number.isNaN(feeRaw) || feeRaw === null ? 0 : Math.abs(feeRaw);
    const wallet = get("wallet") || "";
    const tx = { line, date, kind, asset, qty, usd, fee, wallet };
    if (kind === "sell") {
      const rep = parseReported(get("reported"));
      if (rep === undefined) out.skipped.push(`Line ${line}: "${get("reported")}" in the reported column is not basis, nobasis or none; treated as none.`);
      else if (rep) tx.reported = rep;
    }
    out.transactions.push(tx);
  }
  return out;
}

// ---- lot matching ------------------------------------------------------

function addOneYear(iso) {
  const [y, m, d] = iso.split("-").map(Number);
  const dt = new Date(Date.UTC(y + 1, m - 1, d));
  // Feb 29 acquisition: Date rolls to Mar 1, which is the day after the anniversary.
  if (m === 2 && d === 29) return `${y + 1}-02-28`;
  return dt.toISOString().slice(0, 10);
}

// Long-term means held for MORE than one year: the sale date must fall after the
// first anniversary of the acquisition date.
export function holdingTerm(acquired, sold) {
  return sold > addOneYear(acquired) ? "Long" : "Short";
}

function rateOf(term, rates) {
  return term === "Long" ? rates.longRate : rates.shortRate;
}

function orderLots(lots, method, sale, unitProceeds, rates) {
  const byAcq = (a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : a.seq - b.seq);
  const unitBasis = (l) => l.basis / l.qtyOriginal;
  const arr = lots.slice();
  switch (method) {
    case "FIFO": return arr.sort(byAcq);
    case "LIFO": return arr.sort((a, b) => -byAcq(a, b));
    case "HIFO": return arr.sort((a, b) => unitBasis(b) - unitBasis(a) || byAcq(a, b));
    case "LOFO": return arr.sort((a, b) => unitBasis(a) - unitBasis(b) || byAcq(a, b));
    case "TAXMIN": {
      const tax = (l) => (unitProceeds - unitBasis(l)) * rateOf(holdingTerm(l.date, sale.date), rates);
      return arr.sort((a, b) => tax(a) - tax(b) || byAcq(a, b));
    }
    default: throw new Error(`Unknown method ${method}`);
  }
}

const PRIORITY = { buy: 0, income: 0, transfer: 1, sell: 2 };

// Runs one method over every transaction. Returns pieces (one per lot consumed)
// and the lots still open at the end.
export function matchLots(transactions, { method = "FIFO", perWallet = false, shortRate = 0.24, longRate = 0.15 } = {}) {
  const rates = { shortRate, longRate };
  const ordered = transactions
    .map((t, i) => ({ ...t, seq: i }))
    .sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : PRIORITY[a.kind] - PRIORITY[b.kind] || a.seq - b.seq));
  const books = new Map();
  const bookKey = (t) => `${t.asset}\u0000${perWallet ? t.wallet : ""}`;
  const pieces = [];
  const shortfalls = [];
  for (const t of ordered) {
    if (t.kind === "transfer") {
      // Moving coins between your own wallets is not a sale. With one pool there is nothing to move;
      // per wallet, the chosen lots keep their purchase date and basis in the new wallet.
      if (!perWallet) continue;
      const from = books.get(bookKey(t)) || [];
      const dest = bookKey({ asset: t.asset, wallet: t.toWallet });
      if (!books.has(dest)) books.set(dest, []);
      let left = t.qty;
      const order = method === "TAXMIN" ? "FIFO" : method;
      for (const lot of orderLots(from.filter((l) => l.qty > EPS), order, t, 0, rates)) {
        if (left <= EPS) break;
        const take = Math.min(lot.qty, left);
        const basis = (lot.basis / lot.qtyOriginal) * take;
        books.get(dest).push({ ...lot, wallet: t.toWallet, qty: take, qtyOriginal: take, basis });
        lot.qty -= take;
        left -= take;
      }
      if (left > EPS) shortfalls.push({ asset: t.asset, wallet: t.wallet, line: t.line, date: t.date, qty: left, transfer: true });
      continue;
    }
    const key = bookKey(t);
    if (!books.has(key)) books.set(key, []);
    const lots = books.get(key);
    if (t.kind === "buy" || t.kind === "income") {
      const basis = t.kind === "buy" ? t.usd + t.fee : t.usd;
      lots.push({ date: t.date, seq: t.seq, line: t.line, kind: t.kind, asset: t.asset, wallet: t.wallet, qty: t.qty, qtyOriginal: t.qty, basis });
      continue;
    }
    // sale: fee reduces proceeds
    const netProceeds = t.usd - t.fee;
    const unitProceeds = netProceeds / t.qty;
    let remaining = t.qty;
    const open = lots.filter((l) => l.qty > EPS);
    for (const lot of orderLots(open, method, t, unitProceeds, rates)) {
      if (remaining <= EPS) break;
      const take = Math.min(lot.qty, remaining);
      const share = take / t.qty;
      pieces.push({
        asset: t.asset, wallet: t.wallet, qty: take, saleLine: t.line, lotLine: lot.line,
        acquired: lot.date, sold: t.date,
        proceeds: netProceeds * share,
        basis: (lot.basis / lot.qtyOriginal) * take,
        term: holdingTerm(lot.date, t.date),
        reported: t.reported || "",
        missingBasis: false,
      });
      lot.qty -= take;
      remaining -= take;
    }
    if (remaining > EPS) {
      const share = remaining / t.qty;
      shortfalls.push({ asset: t.asset, wallet: t.wallet, line: t.line, date: t.date, qty: remaining });
      pieces.push({
        asset: t.asset, wallet: t.wallet, qty: remaining, saleLine: t.line, lotLine: null,
        acquired: null, sold: t.date, proceeds: netProceeds * share, basis: 0, term: "Short", reported: t.reported || "", missingBasis: true,
      });
    }
  }
  const openLots = [];
  for (const lots of books.values()) for (const l of lots) if (l.qty > EPS) openLots.push({ ...l });
  return { pieces, openLots, shortfalls };
}

// ---- wash-sale lookalike ----------------------------------------------

function dayNumber(iso) {
  const [y, m, d] = iso.split("-").map(Number);
  return Math.round(Date.UTC(y, m - 1, d) / 86400000);
}

// Crypto is not covered by the wash-sale rule today (IRC 1091 names stock and
// securities), but bills to extend it recur. For each sale at a loss, find
// coins of the same asset bought or received within 30 days either side (other
// than the lots the sale itself used) and show how much loss a stock-style rule
// would defer. Each replacement purchase is used once. Informational only.
export function washLookalike(pieces, txs, year = null) {
  const buys = txs.filter((t) => t.kind === "buy" || t.kind === "income").map((t) => ({ ...t, left: t.qty }));
  const bySale = new Map();
  for (const p of pieces) {
    if (p.missingBasis || (year !== null && yearOf(p.sold) !== year)) continue;
    const g = bySale.get(p.saleLine) || { saleLine: p.saleLine, asset: p.asset, sold: p.sold, lots: new Set(), pieces: [] };
    g.lots.add(p.lotLine);
    g.pieces.push(p);
    bySale.set(p.saleLine, g);
  }
  const items = [];
  for (const g of [...bySale.values()].sort((a, b) => (a.sold < b.sold ? -1 : a.sold > b.sold ? 1 : a.saleLine - b.saleLine))) {
    const losing = g.pieces.filter((p) => p.proceeds < p.basis);
    if (losing.length === 0) continue;
    const lossQty = losing.reduce((a, p) => a + p.qty, 0);
    const loss = losing.reduce((a, p) => a + (p.basis - p.proceeds), 0);
    const sd = dayNumber(g.sold);
    let replaced = 0;
    const lines = [];
    for (const b of buys) {
      if (replaced >= lossQty - EPS) break;
      if (b.asset !== g.asset || b.left <= EPS || g.lots.has(b.line)) continue;
      if (Math.abs(dayNumber(b.date) - sd) > 30) continue;
      const take = Math.min(b.left, lossQty - replaced);
      b.left -= take;
      replaced += take;
      lines.push(b.line);
    }
    if (replaced <= EPS) continue;
    const share = Math.min(1, replaced / lossQty);
    items.push({ saleLine: g.saleLine, asset: g.asset, sold: g.sold, qty: Number(lossQty.toFixed(8)), replacedQty: Number(replaced.toFixed(8)), loss: cents(loss), deferred: cents(loss * share), buyLines: lines });
  }
  return { items, deferred: cents(items.reduce((a, i) => a + i.deferred, 0)) };
}

// ---- reporting ---------------------------------------------------------

export function toRow(p) {
  const proceeds = cents(p.proceeds);
  const basis = cents(p.basis);
  return {
    description: `${trimQty(p.qty)} ${p.asset}`,
    asset: p.asset,
    wallet: p.wallet,
    acquired: p.acquired,
    sold: p.sold,
    proceeds,
    basis,
    gain: cents(proceeds - basis),
    term: p.term,
    reported: p.reported || "",
    box: form8949Box(p.term, p.reported),
    missingBasis: p.missingBasis,
  };
}

// Form 8949 digital-asset boxes (2025 forms): short-term G (1099-DA, basis
// reported), H (1099-DA, basis not reported), I (no 1099-DA); long-term J, K, L.
export function form8949Box(term, reported) {
  const i = reported === "basis" ? 0 : reported === "nobasis" ? 1 : 2;
  return (term === "Long" ? "JKL" : "GHI")[i];
}

function trimQty(q) {
  return String(Number(q.toFixed(8)));
}

export function summarize(rows) {
  const s = { shortGain: 0, longGain: 0, shortProceeds: 0, longProceeds: 0, shortBasis: 0, longBasis: 0 };
  for (const r of rows) {
    const k = r.term === "Long" ? "long" : "short";
    s[`${k}Gain`] += r.gain;
    s[`${k}Proceeds`] += r.proceeds;
    s[`${k}Basis`] += r.basis;
  }
  for (const k of Object.keys(s)) s[k] = cents(s[k]);
  s.totalGain = cents(s.shortGain + s.longGain);
  return s;
}

// Column totals for each part of Form 8949 (Part I short-term, Part II
// long-term) and the combined figure, the numbers that carry to Schedule D.
// Sums the already-rounded rows, so the totals equal what the rows add up to on
// paper. `noBasis` counts rows with no purchase on record, whose zero basis
// overstates the gain until the missing buy is added.
export function form8949Totals(rows) {
  const blank = () => ({ rows: 0, proceeds: 0, basis: 0, gain: 0, noBasis: 0 });
  const t = { short: blank(), long: blank() };
  for (const r of rows) {
    const part = t[r.term === "Long" ? "long" : "short"];
    part.rows += 1;
    part.proceeds += r.proceeds;
    part.basis += r.basis;
    part.gain += r.gain;
    if (r.missingBasis) part.noBasis += 1;
  }
  for (const part of [t.short, t.long]) {
    for (const k of ["proceeds", "basis", "gain"]) part[k] = cents(part[k]);
  }
  t.total = {
    rows: t.short.rows + t.long.rows,
    proceeds: cents(t.short.proceeds + t.long.proceeds),
    basis: cents(t.short.basis + t.long.basis),
    gain: cents(t.short.gain + t.long.gain),
    noBasis: t.short.noBasis + t.long.noBasis,
  };
  return t;
}

// Column totals per Form 8949 box (G to L), only for boxes that have rows, so a
// return can carry each box to its own Form 8949 page.
export function form8949BoxTotals(rows) {
  const t = {};
  for (const r of rows) {
    const b = (t[r.box] ||= { box: r.box, rows: 0, proceeds: 0, basis: 0, gain: 0 });
    b.rows += 1; b.proceeds += r.proceeds; b.basis += r.basis; b.gain += r.gain;
  }
  return Object.values(t).sort((a, b) => (a.box < b.box ? -1 : 1)).map((b) => ({
    ...b, proceeds: cents(b.proceeds), basis: cents(b.basis), gain: cents(b.gain),
  }));
}

// Federal-style netting of short and long results, ignoring NIIT, the $3,000
// ordinary-income loss deduction and carryforwards. A net loss costs nothing here.
export function estimateTax(summary, { shortRate, longRate }) {
  const st = summary.shortGain;
  const lt = summary.longGain;
  let tax;
  if (st >= 0 && lt >= 0) tax = st * shortRate + lt * longRate;
  else if (st < 0 && lt > 0) tax = Math.max(0, lt + st) * longRate;
  else if (st > 0 && lt < 0) tax = Math.max(0, st + lt) * shortRate;
  else tax = 0;
  return cents(tax);
}

// Capital-loss netting with the $3,000 annual limit and indefinite carryforward
// (Schedule D and its Capital Loss Carryover Worksheet, simplified): short-term
// and long-term results net within their own bucket, then against each other; a
// net loss is deductible up to `limit` ($3,000, or $1,500 married filing
// separately) and the rest carries to next year keeping its character, with the
// deduction taken from the short-term loss first. Tax on a net gain uses the
// short and long rates on whatever remains of each bucket. Ignores NIIT, state
// tax and the effect of the deduction on ordinary tax (`deduction` is reported,
// not valued).
export function netCapital(shortGain, longGain, { carryShort = 0, carryLong = 0, limit = 3000, shortRate = 0.24, longRate = 0.15 } = {}) {
  const s = cents(shortGain - Math.abs(carryShort));
  const l = cents(longGain - Math.abs(carryLong));
  const total = cents(s + l);
  let deduction = 0, outShort = 0, outLong = 0, tax = 0;
  if (total < 0) {
    deduction = Math.min(limit, -total);
    const rest = cents(-total - deduction);
    if (s < 0 && l < 0) { outShort = Math.max(0, cents(-s - deduction)); outLong = cents(rest - outShort); }
    else if (s < 0) outShort = rest;
    else outLong = rest;
  } else if (s >= 0 && l >= 0) tax = s * shortRate + l * longRate;
  else if (s < 0) tax = total * longRate;
  else tax = total * shortRate;
  return { shortNet: s, longNet: l, totalNet: total, deduction: cents(deduction), carryShortOut: cents(outShort), carryLongOut: cents(outLong), tax: cents(tax) };
}

// Net investment income tax (IRC section 1411, Form 8960): 3.8% of the smaller of
// net investment income and the amount modified AGI exceeds a threshold that is not
// indexed for inflation. `magi` is the user's income for the year EXCLUDING these
// crypto results (include wages and any staking or mining income); `otherNii` is
// other net investment income (interest, dividends, other gains). The crypto
// result enters both at its netted amount, a net loss only by the allowed
// deduction. Whether staking or mining income is net investment income depends on
// facts (a trade or business is excluded), so it is left to the user via `otherNii`.
export const NIIT_THRESHOLDS = { single: 200000, hoh: 200000, mfj: 250000, qw: 250000, mfs: 125000 };
export const NIIT_RATE = 0.038;
export function niit(netting, { magi, otherNii = 0, status = "single" } = {}) {
  const threshold = NIIT_THRESHOLDS[status];
  if (threshold === undefined || !Number.isFinite(magi) || magi < 0 || !Number.isFinite(otherNii)) return null;
  const crypto = netting.totalNet >= 0 ? netting.totalNet : -netting.deduction;
  const nii = cents(Math.max(0, crypto + otherNii));
  const totalMagi = cents(magi + crypto);
  const over = cents(Math.max(0, totalMagi - threshold));
  const base = Math.min(nii, over);
  const tax = cents(base * NIIT_RATE);
  // What the crypto result alone adds: the same calculation without it.
  const without = cents(Math.min(Math.max(0, otherNii), Math.max(0, magi - threshold)) * NIIT_RATE);
  return { status, threshold, totalMagi, nii, over, base, tax, fromCrypto: cents(tax - without) };
}

// Chains `netCapital` over several years: [{ year, shortGain, longGain }] in
// any order, years with no sales between them carry through unchanged.
export function carryoverChain(yearSummaries, opts = {}) {
  let carryShort = Math.abs(opts.carryShort || 0), carryLong = Math.abs(opts.carryLong || 0);
  const out = [];
  for (const y of [...yearSummaries].sort((a, b) => a.year - b.year)) {
    const r = netCapital(y.shortGain, y.longGain, { ...opts, carryShort, carryLong });
    out.push({ year: y.year, carryShortIn: cents(carryShort), carryLongIn: cents(carryLong), shortGain: y.shortGain, longGain: y.longGain, ...r });
    carryShort = r.carryShortOut; carryLong = r.carryLongOut;
  }
  return out;
}

export function yearOf(iso) {
  return Number(iso.slice(0, 4));
}

// Ordinary income received (staking, mining, airdrops, rewards) in a tax year, by coin and
// by month, valued at the USD amounts the user entered. Each row is also a lot, so the
// same figures are the basis of the coins when they are later sold.
export function incomeReport(txs, year = null) {
  const rows = txs.filter((t) => t.kind === "income" && (year === null || yearOf(t.date) === year));
  const byAsset = new Map(), byMonth = new Map();
  for (const t of rows) {
    const a = byAsset.get(t.asset) || { asset: t.asset, count: 0, qty: 0, usd: 0, first: t.date, last: t.date };
    a.count++; a.qty += t.qty; a.usd += t.usd;
    if (t.date < a.first) a.first = t.date;
    if (t.date > a.last) a.last = t.date;
    byAsset.set(t.asset, a);
    const m = t.date.slice(0, 7);
    byMonth.set(m, (byMonth.get(m) || 0) + t.usd);
  }
  const assets = [...byAsset.values()].map((a) => ({ ...a, qty: Number(a.qty.toFixed(8)), usd: cents(a.usd) })).sort((a, b) => b.usd - a.usd);
  const months = [...byMonth].map(([month, usd]) => ({ month, usd: cents(usd) })).sort((a, b) => (a.month < b.month ? -1 : 1));
  return { year, count: rows.length, total: cents(rows.reduce((n, t) => n + t.usd, 0)), assets, months };
}

export function toIncomeCsv(report) {
  const lines = [["Asset", "Receipts", "Quantity", "First received", "Last received", "Fair market value (USD)"].join(",")];
  for (const a of report.assets) lines.push([a.asset, a.count, a.qty, a.first, a.last, a.usd.toFixed(2)].map(q).join(","));
  lines.push(["Total", report.count, "", "", "", report.total.toFixed(2)].map(q).join(","));
  return lines.join("\n") + "\n";
}

export function analyze(text, options = {}) {
  const { method = "FIFO", year = null, perWallet = false, shortRate = 0.24, longRate = 0.15, carryShort = 0, carryLong = 0, lossLimit = 3000, magi = null, otherNii = 0, filing = "single" } = options;
  const parsed = parseTransactions(text);
  const result = {
    errors: parsed.errors, skipped: parsed.skipped, warnings: [], years: [], year: null,
    rows: [], washLookalike: { items: [], deferred: 0 }, summary: null, tax: null, netting: null, niit: null, carryChain: [], comparison: [], holdings: [], openLots: [], income: 0, incomeReport: null, method, count: parsed.transactions.length,
  };
  if (parsed.errors.length && parsed.transactions.length === 0) return result;
  const txs = parsed.transactions;
  if (txs.length === 0) { result.errors.push("No transactions found."); return result; }

  const saleYears = [...new Set(txs.filter((t) => t.kind === "sell").map((t) => yearOf(t.date)))].sort();
  result.years = saleYears;
  const chosen = year ?? saleYears[saleYears.length - 1] ?? null;
  result.year = chosen;
  const rates = { shortRate, longRate };

  const run = (m) => {
    const { pieces, openLots, shortfalls } = matchLots(txs, { method: m, perWallet, shortRate, longRate });
    const rows = pieces.map(toRow).filter((r) => chosen === null || yearOf(r.sold) === chosen)
      .sort((a, b) => (a.sold < b.sold ? -1 : a.sold > b.sold ? 1 : (a.acquired || "") < (b.acquired || "") ? -1 : 1));
    const summary = summarize(rows);
    return { rows, summary, tax: estimateTax(summary, rates), openLots, shortfalls };
  };

  const main = run(method);
  result.rows = main.rows;
  result.summary = main.summary;
  result.tax = main.tax;
  for (const m of METHODS) {
    const r = m === method ? main : run(m);
    result.comparison.push({
      method: m, label: METHOD_LABELS[m], shortGain: r.summary.shortGain, longGain: r.summary.longGain,
      totalGain: r.summary.totalGain, tax: r.tax,
    });
  }
  {
    const { pieces } = matchLots(txs, { method, perWallet, shortRate, longRate });
    const byYear = new Map();
    for (const p of pieces) {
      const row = toRow(p), y = yearOf(row.sold);
      const a = byYear.get(y) || [];
      a.push(row);
      byYear.set(y, a);
    }
    const sums = [...byYear].map(([y, rs]) => { const sm = summarize(rs); return { year: y, shortGain: sm.shortGain, longGain: sm.longGain }; });
    result.carryChain = carryoverChain(sums, { carryShort, carryLong, limit: lossLimit, shortRate, longRate });
    result.netting = result.carryChain.find((c) => c.year === chosen) || null;
    if (magi !== null && result.netting) result.niit = niit(result.netting, { magi, otherNii, status: filing });
    // The same year under every method, so a method that lowers income tax but
    // raises the 3.8% surtax (or the reverse) shows up in the comparison.
    if (magi !== null && chosen !== null) {
      for (const c of result.comparison) {
        const { pieces: mp } = matchLots(txs, { method: c.method, perWallet, shortRate, longRate });
        const byY = new Map();
        for (const p of mp) { const row = toRow(p), y = yearOf(row.sold); byY.set(y, [...(byY.get(y) || []), row]); }
        const ms = [...byY].map(([y, rs]) => { const sm = summarize(rs); return { year: y, shortGain: sm.shortGain, longGain: sm.longGain }; });
        const n = carryoverChain(ms, { carryShort, carryLong, limit: lossLimit, shortRate, longRate }).find((x) => x.year === chosen);
        const nn = n ? niit(n, { magi, otherNii, status: filing }) : null;
        c.niit = nn ? nn.tax : 0;
      }
    }
  }
  const best = result.comparison.reduce((a, b) => (b.tax < a.tax || (b.tax === a.tax && b.totalGain < a.totalGain) ? b : a));
  result.bestMethod = best.method;
  result.washLookalike = washLookalike(matchLots(txs, { method, perWallet, shortRate, longRate }).pieces, txs, chosen);

  for (const s of main.shortfalls) {
    if (s.transfer) { result.warnings.push(`Line ${s.line} (${s.date}): transferred ${trimQty(s.qty)} ${s.asset} more than the lots on record in wallet "${s.wallet}". Only the coins on record were moved; add the missing buy, income or transfer-in history.`); continue; }
    result.warnings.push(`Line ${s.line} (${s.date}): sold ${trimQty(s.qty)} ${s.asset} more than the lots on record${perWallet && s.wallet ? ` in wallet "${s.wallet}"` : ""}. That part is shown with zero basis; add the missing buy, income or transfer-in history.`);
  }
  const holdings = new Map();
  for (const l of main.openLots) {
    const k = l.asset;
    const h = holdings.get(k) || { asset: k, qty: 0, basis: 0 };
    h.qty += l.qty;
    h.basis += (l.basis / l.qtyOriginal) * l.qty;
    holdings.set(k, h);
  }
  result.holdings = [...holdings.values()].map((h) => ({ asset: h.asset, qty: Number(h.qty.toFixed(8)), basis: cents(h.basis) })).sort((a, b) => b.basis - a.basis);
  result.openLots = main.openLots.map((l) => ({
    asset: l.asset, wallet: l.wallet, acquired: l.date, qty: Number(l.qty.toFixed(8)), basis: cents((l.basis / l.qtyOriginal) * l.qty),
  }));
  result.income = cents(txs.filter((t) => t.kind === "income" && (chosen === null || yearOf(t.date) === chosen)).reduce((a, t) => a + t.usd, 0));
  result.incomeReport = incomeReport(txs, chosen);
  return result;
}

// "BTC=65000, ETH 3200" or one per line -> { BTC: 65000, ETH: 3200 }. Bad entries are reported, never guessed.
export function parsePrices(text) {
  const prices = {};
  const errors = [];
  for (const part of String(text || "").split(/[\n;]+|,(?=\s*[A-Za-z])/)) {
    const t = part.trim();
    if (!t) continue;
    const m = t.match(/^([A-Za-z0-9.\-]+)\s*[=:\s]\s*\$?\s*([0-9][0-9,]*(?:\.[0-9]+)?)$/);
    if (!m) { errors.push(`Could not read "${t}". Write it as BTC=65000.`); continue; }
    const v = Number(m[2].replace(/,/g, ""));
    if (!(v > 0)) { errors.push(`Price for ${m[1]} must be above zero.`); continue; }
    prices[m[1].toUpperCase()] = v;
  }
  return { prices, errors };
}

// Tax-loss harvesting view of the lots still open. For each lot with a price you
// typed: unrealized gain or loss and its term if sold on `asOf`. Then the tax
// saved by selling every losing lot against the year's realized result
// (`summary` from analyze, already net of the chosen method). Biggest tax saved
// per lot first. No wash-sale rule is applied; see the page for why that is a
// question of current law, not of arithmetic.
export function harvestPlan(openLots, prices, { asOf, summary = null, shortRate = 0.24, longRate = 0.15 } = {}) {
  const base = summary || { shortGain: 0, longGain: 0 };
  const lots = [];
  const unpriced = new Set();
  for (const l of openLots) {
    const price = prices[l.asset];
    if (!price) { unpriced.add(l.asset); continue; }
    const value = cents(l.qty * price);
    const gain = cents(value - l.basis);
    const term = holdingTerm(l.acquired, asOf);
    lots.push({ asset: l.asset, wallet: l.wallet, acquired: l.acquired, qty: l.qty, basis: l.basis, value, gain, term });
  }
  const losers = lots.filter((l) => l.gain < 0);
  const net = (extraShort, extraLong) => estimateTax({ shortGain: base.shortGain + extraShort, longGain: base.longGain + extraLong }, { shortRate, longRate });
  const shortLoss = cents(losers.filter((l) => l.term === "Short").reduce((a, l) => a + l.gain, 0));
  const longLoss = cents(losers.filter((l) => l.term === "Long").reduce((a, l) => a + l.gain, 0));
  const taxBefore = net(0, 0);
  const taxAfter = net(shortLoss, longLoss);
  // Standalone saving per lot (against the current result), for ranking only.
  for (const l of losers) l.taxSaved = cents(taxBefore - (l.term === "Short" ? net(l.gain, 0) : net(0, l.gain)));
  losers.sort((a, b) => b.taxSaved - a.taxSaved || a.gain - b.gain);
  return {
    asOf, lots, losers, unpriced: [...unpriced].sort(),
    unrealizedGain: cents(lots.reduce((a, l) => a + l.gain, 0)),
    shortLoss, longLoss, taxBefore, taxAfter, taxSaved: cents(taxBefore - taxAfter),
    unusedLoss: cents(Math.max(0, -(base.shortGain + shortLoss + base.longGain + longLoss))),
  };
}

function addDays(iso, n) {
  const [y, m, d] = iso.split("-").map(Number);
  return new Date(Date.UTC(y, m - 1, d + n)).toISOString().slice(0, 10);
}

// Wait-for-long-term view: lots you hold at a gain that are still short-term on `asOf` but
// turn long-term within `windowDays`. A lot is long-term from the day after its first
// anniversary (holdingTerm). For each: the first long-term sale date, days to wait, the
// estimated tax saved by selling then instead of on `asOf` at the same price (against the
// year's result in `summary`), and `breakEvenFall`, how far the lot's value can drop while
// waiting before waiting leaves you with less cash after tax than selling now. Prices are
// yours; fees, state tax and the year the sale lands in are not modelled.
export function waitPlan(openLots, prices, { asOf, windowDays = 90, summary = null, shortRate = 0.24, longRate = 0.15 } = {}) {
  const base = summary || { shortGain: 0, longGain: 0 };
  const rates = { shortRate, longRate };
  const unpriced = new Set();
  const lots = [];
  for (const l of openLots) {
    const price = prices[l.asset];
    if (!price) { unpriced.add(l.asset); continue; }
    if (holdingTerm(l.acquired, asOf) !== "Short") continue;
    const longFrom = addDays(addOneYear(l.acquired), 1);
    const days = Math.round((Date.parse(longFrom) - Date.parse(asOf)) / 86400000);
    if (days > windowDays) continue;
    const value = cents(l.qty * price);
    const gain = cents(value - l.basis);
    if (gain <= 0) continue;
    const taxNow = estimateTax({ shortGain: base.shortGain + gain, longGain: base.longGain }, rates) - estimateTax(base, rates);
    const taxLater = estimateTax({ shortGain: base.shortGain, longGain: base.longGain + gain }, rates) - estimateTax(base, rates);
    const taxSaved = cents(taxNow - taxLater);
    if (taxSaved <= 0) continue;
    const fall = cents(Math.max(0, gain * (shortRate - longRate) / (1 - longRate)));
    lots.push({ asset: l.asset, wallet: l.wallet, acquired: l.acquired, qty: l.qty, basis: l.basis, value, gain, longFrom, days, taxSaved, breakEvenFall: fall, breakEvenFallPct: value > 0 ? Number((fall / value * 100).toFixed(1)) : 0 });
  }
  lots.sort((a, b) => a.days - b.days || b.taxSaved - a.taxSaved);
  return { asOf, windowDays, lots, unpriced: [...unpriced].sort(), taxSaved: cents(lots.reduce((a, l) => a + l.taxSaved, 0)) };
}

// Sell planner: which of the lots you still hold to sell for `asset` at a price you typed,
// under each method, and what each choice adds to the year's estimated tax. Give `qty`
// (coins) or `cash` (dollars of proceeds wanted, before the fee). `summary` is the year's
// realized result so far, so a sale of losing lots can offset it and a sale of gains stacks on it.
// A request larger than the holding is cut to the holding and flagged, never invented.
export function planSale(openLots, { asset, price, asOf, qty = null, cash = null, feeRate = 0, summary = null, shortRate = 0.24, longRate = 0.15 }) {
  const rates = { shortRate, longRate };
  const base = summary || { shortGain: 0, longGain: 0 };
  const held = openLots.filter((l) => l.asset === asset && l.qty > EPS)
    .map((l, i) => ({ date: l.acquired, seq: i, wallet: l.wallet, qty: l.qty, qtyOriginal: l.qty, basis: l.basis }));
  const heldQty = held.reduce((a, l) => a + l.qty, 0);
  const wanted = qty !== null ? qty : cash !== null ? cash / (price * (1 - feeRate)) : 0;
  const target = Math.min(wanted, heldQty);
  const taxBefore = estimateTax(base, rates);
  const sale = { date: asOf };
  const options = METHODS.map((method) => {
    const lots = held.map((l) => ({ ...l }));
    let left = target;
    const taken = [];
    for (const lot of orderLots(lots, method, sale, price * (1 - feeRate), rates)) {
      if (left <= EPS) break;
      const take = Math.min(lot.qty, left);
      const proceeds = take * price * (1 - feeRate);
      const basis = (lot.basis / lot.qtyOriginal) * take;
      taken.push({ wallet: lot.wallet, acquired: lot.date, qty: Number(take.toFixed(8)), proceeds: cents(proceeds), basis: cents(basis), gain: cents(proceeds - basis), term: holdingTerm(lot.date, asOf) });
      left -= take;
    }
    const sum = (term) => cents(taken.filter((t) => t.term === term).reduce((a, t) => a + t.gain, 0));
    const shortGain = sum("Short"), longGain = sum("Long");
    const proceeds = cents(taken.reduce((a, t) => a + t.proceeds, 0));
    const extraTax = cents(estimateTax({ shortGain: base.shortGain + shortGain, longGain: base.longGain + longGain }, rates) - taxBefore);
    return { method, label: METHOD_LABELS[method], lots: taken, proceeds, basis: cents(taken.reduce((a, t) => a + t.basis, 0)), shortGain, longGain, gain: cents(shortGain + longGain), extraTax, keep: cents(proceeds - extraTax) };
  });
  const best = options.reduce((a, b) => (b.extraTax < a.extraTax ? b : a));
  return { asset, price, asOf, requested: Number(wanted.toFixed(8)), qty: Number(target.toFixed(8)), heldQty: Number(heldQty.toFixed(8)), capped: wanted > heldQty + EPS, taxBefore, options, bestMethod: best.method };
}

// Written lot-identification record for one option of a sell plan: the units a sale is to
// use, in a form to date and keep (or send to the platform) before selling. Specific
// identification generally depends on the choice being made no later than the sale and being
// provable, which is what this page is for; whether it is enough for you is for your preparer.
export function idRecord(plan, method) {
  const o = plan.options.find((x) => x.method === method);
  if (!o || !o.lots.length) return null;
  const lines = [
    `Specific identification of units to be sold: ${plan.asset}`,
    `Planned sale date: ${plan.asOf}`,
    `Planned quantity: ${o.lots.reduce((a, l) => a + l.qty, 0).toFixed(8).replace(/\.?0+$/, "")} ${plan.asset} at an assumed ${plan.price} USD per coin`,
    "",
    "Units to be treated as sold (wallet / account, date acquired, quantity, cost basis in USD):",
  ];
  for (const l of o.lots) lines.push(`  - ${l.wallet || "(no wallet recorded)"}; acquired ${l.acquired}; ${l.qty} ${plan.asset}; basis ${l.basis.toFixed(2)}`);
  lines.push("", "Written before the sale. Date and time it, and keep it with the exchange or wallet records. Lots chosen by the " + o.label + " rule from the transaction file as typed; prices are assumed, not fetched.", "Arithmetic on figures you typed, not tax advice: confirm with a tax professional that specific identification is available to you and that this record meets the rule.");
  const csv = ["wallet,asset,date_acquired,quantity,cost_basis_usd"].concat(o.lots.map((l) => [q(l.wallet || ""), q(plan.asset), l.acquired, l.qty, l.basis.toFixed(2)].join(","))).join("\n") + "\n";
  return { method, text: lines.join("\n") + "\n", csv };
}

const q = (v) => {
  const s = v === null || v === undefined ? "" : String(v);
  return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

// CSV in Form 8949 column order, ready to paste into tax software or hand to a preparer.
// Gift of appreciated coins to a public charity: only lots held over a year count at
// market value, so pick those with the most gain per coin first. Compares with selling
// the same lots (gain tax avoided). `deductionRate` is yours (0 = ignore the deduction).
export function donationPlan(openLots, { asset, price, asOf, qty, longRate = 0.15, deductionRate = 0 }) {
  const held = openLots.filter((l) => l.asset === asset && l.qty > EPS && holdingTerm(l.acquired, asOf) === "Long")
    .map((l) => ({ wallet: l.wallet, acquired: l.acquired, qty: l.qty, perCoin: l.basis / l.qty, basis: l.basis }))
    .sort((a, b) => a.perCoin - b.perCoin);
  const longQty = held.reduce((a, l) => a + l.qty, 0);
  const target = Math.min(qty, longQty);
  let left = target;
  const lots = [];
  for (const l of held) {
    if (left <= EPS) break;
    const take = Math.min(l.qty, left);
    const value = take * price, basis = l.perCoin * take;
    lots.push({ wallet: l.wallet, acquired: l.acquired, qty: Number(take.toFixed(8)), value: cents(value), basis: cents(basis), gain: cents(value - basis) });
    left -= take;
  }
  const value = cents(lots.reduce((a, l) => a + l.value, 0));
  const basis = cents(lots.reduce((a, l) => a + l.basis, 0));
  const gain = cents(value - basis);
  const taxAvoided = cents(Math.max(0, gain) * longRate);
  const deductionValue = cents(value * deductionRate);
  return { asset, price, asOf, requested: qty, qty: Number(target.toFixed(8)), longQty: Number(longQty.toFixed(8)), capped: qty > longQty + EPS, lots, value, basis, gain, taxAvoided, deductionValue, totalBenefit: cents(taxAvoided + deductionValue) };
}

// Reconcile against the broker's Form 1099-DA: type or paste the per-asset (or
// per-sale) proceeds and basis the broker reported, and compare each coin with
// what your own lot matching produced. A basis gap is the usual cause of an
// inflated gain on a 1099-DA (the broker saw only its own purchases).
const REC_ALIASES = {
  asset: ["asset", "coin", "token", "symbol", "digital asset", "code"],
  proceeds: ["proceeds", "gross proceeds", "proceeds usd", "amount received"],
  basis: ["basis", "cost basis", "cost", "basis usd"],
};
export function parse1099da(text) {
  const grid = parseCsv(text).filter((r) => r.some((c) => String(c).trim()));
  const out = { entries: {}, errors: [] };
  if (grid.length < 2) { out.errors.push("Need a header row and at least one coin."); return out; }
  const head = grid[0].map((h) => String(h).trim().toLowerCase());
  const col = {};
  for (const [k, names] of Object.entries(REC_ALIASES)) col[k] = head.findIndex((h) => names.includes(h));
  if (col.asset < 0 || col.proceeds < 0) { out.errors.push("Header needs an asset column and a proceeds column."); return out; }
  const num = (v) => { const n = Number(String(v ?? "").replace(/[$,\s]/g, "")); return String(v ?? "").trim() === "" || !Number.isFinite(n) ? null : n; };
  grid.slice(1).forEach((r, i) => {
    const asset = String(r[col.asset] ?? "").trim().toUpperCase();
    const proceeds = num(r[col.proceeds]);
    if (!asset || proceeds === null) { out.errors.push(`Row ${i + 2}: needs an asset and a number for proceeds.`); return; }
    const basis = col.basis >= 0 ? num(r[col.basis]) : null;
    const e = (out.entries[asset] ||= { proceeds: 0, basis: null });
    e.proceeds += proceeds;
    if (basis !== null) e.basis = (e.basis ?? 0) + basis;
  });
  return out;
}

export function reconcile1099da(rows, broker, { tolerance = 1 } = {}) {
  const mine = {};
  for (const r of rows) {
    const m = (mine[r.asset] ||= { proceeds: 0, basis: 0 });
    m.proceeds += r.proceeds;
    m.basis += r.basis;
  }
  const items = [];
  for (const asset of [...new Set([...Object.keys(mine), ...Object.keys(broker)])].sort()) {
    const m = mine[asset], b = broker[asset];
    const it = { asset, myProceeds: m ? cents(m.proceeds) : null, myBasis: m ? cents(m.basis) : null, brokerProceeds: b ? cents(b.proceeds) : null, brokerBasis: b && b.basis !== null ? cents(b.basis) : null };
    it.proceedsDiff = m && b ? cents(b.proceeds - m.proceeds) : null;
    it.basisDiff = m && b && it.brokerBasis !== null ? cents(it.brokerBasis - m.basis) : null;
    it.status = !b ? "not on 1099-DA" : !m ? "not in your sales" : Math.abs(it.proceedsDiff) > tolerance ? "proceeds differ" : it.basisDiff !== null && Math.abs(it.basisDiff) > tolerance ? "basis differs" : "matches";
    items.push(it);
  }
  return { items, mismatches: items.filter((i) => i.status !== "matches").length };
}

export function toForm8949Csv(rows) {
  // Box column only when the file says which sales a broker reported on a 1099-DA.
  const boxes = rows.some((r) => r.reported);
  const head = ["Description of property", "Date acquired", "Date sold", "Proceeds", "Cost or other basis", "Gain or loss", "Term", ...(boxes ? ["Box"] : []), "Note"];
  const lines = [head.join(",")];
  for (const r of rows) {
    lines.push([
      r.description, r.acquired || "VARIOUS", r.sold, r.proceeds.toFixed(2), r.basis.toFixed(2), r.gain.toFixed(2), r.term,
      ...(boxes ? [r.box] : []),
      r.missingBasis ? "No basis on record" : "",
    ].map(q).join(","));
  }
  return lines.join("\n") + "\n";
}

// Tax-software import rows (the five-column crypto template that online
// filing products document: currency, purchase date, cost basis, sale date,
// proceeds; dates MM/DD/YYYY). Rows with no purchase on record are left out, never
// given a basis of zero; turboTaxSkipped counts them so the caller can say so.
const usDate = (iso) => (/^\d{4}-\d{2}-\d{2}/.test(iso || "") ? `${iso.slice(5, 7)}/${iso.slice(8, 10)}/${iso.slice(0, 4)}` : "Various");
export function toTurboTaxCsv(rows) {
  const lines = ["Currency Name,Purchase Date,Cost Basis,Date Sold,Proceeds"];
  for (const r of rows) {
    if (r.missingBasis) continue;
    lines.push([r.asset, usDate(r.acquired), r.basis.toFixed(2), usDate(r.sold), r.proceeds.toFixed(2)].map(q).join(","));
  }
  return lines.join("\n") + "\n";
}
export const turboTaxSkipped = (rows) => rows.filter((r) => r.missingBasis).length;

export const SAMPLE_CSV = `date,type,asset,quantity,total,fee,wallet
2023-01-10,buy,BTC,0.50,10000,10,Exchange A
2023-06-15,buy,BTC,0.50,15000,15,Exchange A
2024-02-01,buy,BTC,0.25,12000,12,Exchange A
2024-03-05,income,ETH,2,5000,0,Exchange A
2024-09-20,sell,BTC,0.60,36000,36,Exchange A
2024-11-02,sell,ETH,1,3300,3,Exchange A
`;

cli.mjs.text:
#!/usr/bin/env node
// Match crypto sales to purchase lots from exchange CSVs, in a terminal.
//
//   node cli.mjs coinbase.csv                       # FIFO summary for the latest sale year
//   node cli.mjs --method HIFO --year 2024 a.csv b.csv
//   node cli.mjs --form8949 8949.csv kraken.csv      # write Form 8949 style rows
//   node cli.mjs --json coinbase.csv                 # machine-readable
//   cat history.csv | node cli.mjs -                 # read stdin
//   node cli.mjs --example                           # built-in sample
//
// Zero dependencies, no network: files are read locally and nothing is sent.
// Same matching as the web page (calc.mjs) and the same exchange readers
// (importers.mjs), so the numbers agree with the page.

import { readFile, writeFile } from "node:fs/promises";
import process from "node:process";
import { analyze, planSale, idRecord, donationPlan, parsePrices, parse1099da, reconcile1099da, harvestPlan, waitPlan, toForm8949Csv, toTurboTaxCsv, turboTaxSkipped, toIncomeCsv, form8949Totals, form8949BoxTotals, METHODS, METHOD_LABELS, NIIT_THRESHOLDS, SAMPLE_CSV } from "./calc.mjs";
import { convertMany, FORMAT_LABELS } from "./importers.mjs";

const USAGE = `Crypto cost basis from exchange CSVs: lot matching, method comparison, Form 8949 style rows.

Usage:
  node cli.mjs [options] <file.csv ...| ->

Options:
  --method <m>        FIFO (default), LIFO, HIFO, LOFO or TAXMIN
  --year <yyyy>       tax year of the sales (default: the latest year with a sale)
  --per-wallet        match each sale only against lots in the same wallet
  --carry-short <usd>  short-term loss carried in from before the file starts
  --carry-long <usd>   long-term loss carried in from before the file starts
  --mfs                $1,500 annual loss deduction (married filing separately)
  --magi <usd>         your other income for the year (excluding these results): adds the 3.8% net investment income tax
  --other-nii <usd>    other net investment income (interest, dividends, other gains) for that estimate
  --filing <status>    single (default), mfj, mfs, hoh or qw: sets the NIIT threshold
  --short-rate <pct>  short-term rate for the tax estimate (default 24)
  --long-rate <pct>   long-term rate for the tax estimate (default 15)
  --sell <COIN>       sell planner: compare the five methods for selling COIN; needs --price and --qty or --cash
  --donate <COIN>     gift planner: which long-held lots of COIN to give to a public charity, and the gain tax avoided; needs --price and --qty
  --deduction-rate <r> your rate (0-1) to value the deduction in --donate (default 0: deduction ignored)
  --id-record <METHOD> with --sell: print a written lot-identification record for that method's lots, to date and keep before selling
  --price <usd>       price per coin for --sell or --donate
  --qty <coins>       coins to sell with --sell
  --cash <usd>        dollars to raise with --sell (used when --qty is absent)
  --sale-date <date>  date of the planned sale or price check (default: today)
  --prices <list>     prices you type, e.g. "BTC=65000,ETH=3200": adds tax-loss harvesting and wait-for-long-term (90 days) views of the lots you still hold
  --form8949 <file>   also write Form 8949 style rows to this file
  --tax-software <file> also write the sales as a Currency/Purchase Date/Cost Basis/Date Sold/Proceeds CSV for tax-software import (rows with no purchase on record are left out and counted)
  --income-csv <file> also write the year's staking/mining/airdrop income by coin to this file
  --reconcile <file>  compare each coin with the proceeds and basis your broker reported on Form 1099-DA (CSV: asset,proceeds,basis)
  --json              print the full analysis as JSON
  --example           use the built-in sample instead of a file
  -h, --help          this message

Reads Coinbase, Kraken, Binance.US, Crypto.com App, Gemini, Bitstamp, Cash App, Robinhood, Koinly universal CSV and Coinbase Pro fills exports or the
plain CSV (date,type,asset,quantity,total,fee,wallet). Several files are
merged. Arithmetic on the figures in your files, not tax advice: it fetches no
prices, and rows an export gives no USD value for are flagged, never zero.
`;

export function parseArgs(argv) {
  const opts = { files: [], method: "FIFO", year: null, perWallet: false, shortRate: 0.24, longRate: 0.15, form8949: null, taxSoftware: null, incomeCsv: null, carryShort: 0, carryLong: 0, lossLimit: 3000, json: false, example: false, help: false };
  const need = (i, arg) => { if (i >= argv.length) throw new Error(`${arg} needs a value`); return argv[i]; };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "-h" || arg === "--help") opts.help = true;
    else if (arg === "--json") opts.json = true;
    else if (arg === "--example") opts.example = true;
    else if (arg === "--per-wallet") opts.perWallet = true;
    else if (arg === "--method") {
      const m = need(++i, arg).toUpperCase();
      if (!METHODS.includes(m)) throw new Error(`--method must be one of ${METHODS.join(", ")}`);
      opts.method = m;
    } else if (arg === "--year") {
      const y = Number(need(++i, arg));
      if (!Number.isInteger(y) || y < 2009 || y > 2100) throw new Error("--year needs a four-digit year");
      opts.year = y;
    } else if (arg === "--short-rate" || arg === "--long-rate") {
      const v = Number(need(++i, arg));
      if (!Number.isFinite(v) || v < 0 || v > 100) throw new Error(`${arg} needs a percent between 0 and 100`);
      opts[arg === "--short-rate" ? "shortRate" : "longRate"] = v / 100;
    } else if (arg === "--carry-short" || arg === "--carry-long") {
      const v = Number(need(++i, arg));
      if (!Number.isFinite(v) || v < 0) throw new Error(`${arg} needs a positive dollar amount`);
      opts[arg === "--carry-short" ? "carryShort" : "carryLong"] = v;
    } else if (arg === "--mfs") opts.lossLimit = 1500;
    else if (arg === "--magi" || arg === "--other-nii") {
      const v = Number(need(++i, arg));
      if (!Number.isFinite(v) || (arg === "--magi" && v < 0)) throw new Error(`${arg} needs a dollar amount`);
      opts[arg === "--magi" ? "magi" : "otherNii"] = v;
    } else if (arg === "--filing") {
      const f = need(++i, arg).toLowerCase();
      if (!(f in NIIT_THRESHOLDS)) throw new Error(`--filing must be one of ${Object.keys(NIIT_THRESHOLDS).join(", ")}`);
      opts.filing = f;
    }
    else if (arg === "--sell") opts.sell = need(++i, arg).toUpperCase();
    else if (arg === "--id-record") { opts.idRecord = need(++i, arg).toUpperCase(); if (!METHODS.includes(opts.idRecord)) throw new Error(`--id-record must be one of ${METHODS.join(", ")}`); }
    else if (arg === "--donate") opts.donate = need(++i, arg).toUpperCase();
    else if (arg === "--deduction-rate") opts.deductionRate = Number(need(++i, arg));
    else if (arg === "--price" || arg === "--qty" || arg === "--cash") {
      const v = Number(need(++i, arg));
      if (!(v > 0)) throw new Error(`${arg} needs a number above zero`);
      opts[arg.slice(2)] = v;
    } else if (arg === "--sale-date") {
      const d = need(++i, arg);
      if (!/^\d{4}-\d{2}-\d{2}$/.test(d)) throw new Error("--sale-date needs yyyy-mm-dd");
      opts.saleDate = d;
    }
    else if (arg === "--prices") {
      const { prices, errors } = parsePrices(need(++i, arg));
      if (errors.length) throw new Error(`--prices: ${errors[0]}`);
      if (!Object.keys(prices).length) throw new Error("--prices needs at least one coin, e.g. BTC=65000");
      opts.prices = prices;
    }
    else if (arg === "--reconcile") opts.reconcile = need(++i, arg);
    else if (arg === "--form8949") opts.form8949 = need(++i, arg);
    else if (arg === "--tax-software") opts.taxSoftware = need(++i, arg);
    else if (arg === "--income-csv") opts.incomeCsv = need(++i, arg);
    else if (arg.startsWith("-") && arg !== "-") throw new Error(`unknown option: ${arg}`);
    else opts.files.push(arg);
  }
  return opts;
}

const usd = (n) => (n < 0 ? "-$" : "$") + Math.abs(n).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

// files: [{ name, text }]. Returns { result, formats, notes, csv, error }.
export function run(files, opts = {}) {
  const { formats, csv, notes } = convertMany(files);
  const result = analyze(csv, { method: opts.method || "FIFO", year: opts.year ?? null, perWallet: !!opts.perWallet, shortRate: opts.shortRate ?? 0.24, longRate: opts.longRate ?? 0.15, carryShort: opts.carryShort || 0, carryLong: opts.carryLong || 0, lossLimit: opts.lossLimit || 3000, magi: opts.magi ?? null, otherNii: opts.otherNii || 0, filing: opts.filing || "single" });
  const error = result.errors.length && result.rows.length === 0 ? result.errors.join("; ") : null;
  return { result, formats, notes, csv, error };
}

export function render({ result, formats, notes }, opts = {}) {
  const out = [];
  out.push(`Read ${result.count} transactions (${[...new Set(formats)].map((f) => FORMAT_LABELS[f] || f).join(", ")}).`);
  for (const n of notes) out.push(`  note: ${n}`);
  for (const e of result.errors) out.push(`  problem: ${e}`);
  for (const s of result.skipped || []) out.push(`  skipped: ${typeof s === "string" ? s : JSON.stringify(s)}`);
  if (result.year === null) { out.push("No sales found, so there is nothing to match."); return out.join("\n") + "\n"; }
  const s = result.summary, t = totalsLine(result);
  out.push("", `Sales in ${result.year}, ${METHOD_LABELS[result.method]}${opts.perWallet ? ", per wallet" : ""}`);
  out.push(`  short-term ${usd(s.shortGain)}   long-term ${usd(s.longGain)}   total ${usd(s.totalGain)}   income received ${usd(result.income)}`);
  out.push(`  estimated tax ${usd(result.tax)} at ${(opts.shortRate ?? 0.24) * 100}% short / ${(opts.longRate ?? 0.15) * 100}% long`);
  if (t) out.push(`  ${t}`);
  if (result.carryChain.length) {
    out.push("", `Loss limit and carryforward (${usd(opts.lossLimit || 3000)} a year; years chained from the first sale in the file):`);
    for (const c of result.carryChain) out.push(`  ${c.year}  carried in ${usd(c.carryShortIn + c.carryLongIn).padStart(12)}   net ${usd(c.totalNet).padStart(13)}   deductible ${usd(c.deduction).padStart(10)}   carried out ${usd(c.carryShortOut + c.carryLongOut).padStart(12)}   tax ${usd(c.tax).padStart(11)}${c.year === result.year ? "   <- shown year" : ""}`);
  }
  if (result.niit) {
    const n = result.niit;
    out.push("", `Net investment income tax (3.8%, ${n.status}, threshold ${usd(n.threshold)}): ${usd(n.tax)} on ${usd(n.base)}; the crypto result adds ${usd(n.fromCrypto)} of it. Your MAGI with these results is ${usd(n.totalMagi)}.`);
  }
  const ir = result.incomeReport;
  if (ir && ir.count) {
    out.push("", `Income received in ${ir.year} (staking, mining, airdrops; ordinary income, not in the gains above): ${usd(ir.total)} from ${ir.count} receipt(s)`);
    for (const a of ir.assets) out.push(`  ${a.asset.padEnd(8)} ${String(a.qty).padStart(14)}   ${usd(a.usd).padStart(12)}   ${a.count} receipt(s), ${a.first} to ${a.last}`);
  }
  const wl = result.washLookalike;
  if (wl && wl.items.length) {
    out.push("", `Wash-sale lookalike (crypto is not covered by the wash-sale rule today; a stock-style rule would defer ${usd(wl.deferred)} of ${result.year} losses):`);
    for (const i of wl.items) out.push(`  line ${String(i.saleLine).padEnd(4)} ${i.sold}  ${i.asset.padEnd(8)} loss ${usd(i.loss).padStart(11)}   re-bought ${i.replacedQty} of ${i.qty} within 30 days   would defer ${usd(i.deferred).padStart(10)}`);
  }
  out.push("", "Method comparison (same sales):");
  for (const c of result.comparison) out.push(`  ${c.label.padEnd(24)} gain ${usd(c.totalGain).padStart(14)}   tax ${usd(c.tax).padStart(12)}${c.niit !== undefined ? `   NIIT ${usd(c.niit).padStart(10)}` : ""}${c.method === result.bestMethod ? "   <- lowest estimated tax" : ""}`);
  if (result.holdings.length) {
    out.push("", "Still held:");
    for (const h of result.holdings) out.push(`  ${h.asset.padEnd(8)} ${String(h.qty).padStart(14)}   basis ${usd(h.basis)}`);
  }
  for (const w of result.warnings) out.push("", `warning: ${w}`);
  return out.join("\n") + "\n";
}

export function renderPlan(p) {
  if (!p.qty) return `\nSell plan: no ${p.asset} on record to sell.\n`;
  const out = ["", `Sell plan: ${p.qty} ${p.asset} at ${usd(p.price)} on ${p.asOf}${p.capped ? ` (asked for ${p.requested}; only ${p.heldQty} on record)` : ""}`];
  for (const o of p.options) out.push(`  ${o.label.padEnd(24)} proceeds ${usd(o.proceeds).padStart(12)}   gain ${usd(o.gain).padStart(12)}   extra tax ${usd(o.extraTax).padStart(11)}${o.method === p.bestMethod ? "   <- least extra tax" : ""}`);
  out.push("  A negative extra tax means the sale lowers the year's estimated tax. Estimate only; which lots you may sell depends on your records.");
  return out.join("\n") + "\n";
}

export function renderPrices(h, w) {
  const out = ["", `Tax-loss harvesting on ${h.asOf} (prices you typed; no wash-sale rule applied)`];
  if (!h.losers.length) out.push("  No priced lot is under water.");
  for (const l of h.losers) out.push(`  ${l.asset.padEnd(8)} bought ${l.acquired}  ${String(l.qty).padStart(12)}   loss ${usd(l.gain).padStart(12)}   ${l.term}-term   tax saved ${usd(l.taxSaved).padStart(10)}`);
  if (h.losers.length) out.push(`  Selling all of them: estimated tax ${usd(h.taxBefore)} -> ${usd(h.taxAfter)} (saves ${usd(h.taxSaved)})${h.unusedLoss ? `; ${usd(h.unusedLoss)} of loss is left over` : ""}.`);
  if (h.unpriced.length) out.push(`  No price given for: ${h.unpriced.join(", ")}.`);
  out.push("", `Wait for long-term: gains that turn long-term within ${w.windowDays} days of ${w.asOf}`);
  if (!w.lots.length) out.push("  None.");
  for (const l of w.lots) out.push(`  ${l.asset.padEnd(8)} bought ${l.acquired}  gain ${usd(l.gain).padStart(12)}   long-term from ${l.longFrom} (${l.days} days)   saves ${usd(l.taxSaved).padStart(10)}   price may fall ${l.breakEvenFallPct}% first`);
  return out.join("\n") + "\n";
}

export function renderDonation(d) {
  if (!d.qty) return `\nGift plan: no ${d.asset} held over a year on record. Short-term lots are not valued at market for a gift.\n`;
  const out = ["", `Gift plan: ${d.qty} ${d.asset} at ${usd(d.price)} on ${d.asOf}${d.capped ? ` (asked for ${d.requested}; only ${d.longQty} held over a year)` : ""}`];
  for (const l of d.lots) out.push(`  ${l.acquired}  ${String(l.qty).padStart(12)}  value ${usd(l.value).padStart(12)}  basis ${usd(l.basis).padStart(12)}  gain ${usd(l.gain).padStart(12)}`);
  out.push(`  Value ${usd(d.value)}, gain never taxed ${usd(d.gain)}, long-term tax avoided ${usd(d.taxAvoided)}` + (d.deductionValue ? `, deduction worth ${usd(d.deductionValue)}` : "") + ".");
  out.push("  Estimate only: deduction limits, appraisal rules and itemizing decide the rest; ask a tax professional.");
  return out.join("\n") + "\n";
}

export function renderReconcile(rec) {
  const d = (v) => (v === null ? "-" : usd(v));
  const out = ["", "Form 1099-DA check (your lot matching vs the broker's figures)"];
  for (const i of rec.items) out.push(`  ${i.asset.padEnd(8)} proceeds ${d(i.myProceeds).padStart(12)} vs ${d(i.brokerProceeds).padStart(12)}  basis ${d(i.myBasis).padStart(12)} vs ${d(i.brokerBasis).padStart(12)}  ${i.status}`);
  out.push(rec.mismatches ? `  ${rec.mismatches} coin(s) differ. A basis gap usually means the broker did not see purchases made elsewhere; keep your records and ask a tax professional how to report it.` : "  Everything matches.");
  return out.join("\n") + "\n";
}

function totalsLine(result) {
  const f = form8949Totals(result.rows);
  const bt = result.rows.some((r) => r.reported) ? "\n" + form8949BoxTotals(result.rows).map((b) => `Box ${b.box}: ${b.rows} row(s), proceeds ${usd(b.proceeds)}, basis ${usd(b.basis)}, gain ${usd(b.gain)}`).join("\n") : "";
  return bt + (f.total.noBasis ? `${f.total.noBasis} row(s) have no purchase on record (zero basis); fix before filing.` : "");
}

async function readInput(name) {
  if (name === "-") {
    const chunks = [];
    for await (const c of process.stdin) chunks.push(c);
    return { name: "stdin", text: Buffer.concat(chunks).toString("utf8") };
  }
  return { name, text: await readFile(name, "utf8") };
}

export async function main(argv) {
  let opts;
  try { opts = parseArgs(argv); } catch (e) { process.stderr.write(`${e.message}\n\n${USAGE}`); return 2; }
  if (opts.help || (!opts.files.length && !opts.example)) { process.stdout.write(USAGE); return opts.help ? 0 : 2; }
  let files;
  try { files = opts.example ? [{ name: "example", text: SAMPLE_CSV }] : await Promise.all(opts.files.map(readInput)); }
  catch (e) { process.stderr.write(`cannot read input: ${e.message}\n`); return 2; }
  const r = run(files, opts);
  if (r.error) { process.stderr.write(`${r.error}\n`); return 1; }
  if (opts.idRecord && !opts.sell) { process.stderr.write("--id-record needs --sell\n"); return 2; }
  if (opts.sell) {
    if (!opts.price || (!opts.qty && !opts.cash)) { process.stderr.write("--sell needs --price and --qty or --cash\n"); return 2; }
  }
  if (opts.donate && (!opts.price || !opts.qty)) { process.stderr.write("--donate needs --price and --qty\n"); return 2; }
  if (opts.incomeCsv) await writeFile(opts.incomeCsv, toIncomeCsv(r.result.incomeReport));
  if (opts.form8949) await writeFile(opts.form8949, toForm8949Csv(r.result.rows));
  if (opts.taxSoftware) {
    await writeFile(opts.taxSoftware, toTurboTaxCsv(r.result.rows));
    const n = turboTaxSkipped(r.result.rows);
    if (n) process.stderr.write(`--tax-software: ${n} sale row(s) with no purchase on record were left out\n`);
  }
  let rec = null;
  if (opts.reconcile) {
    let bt;
    try { bt = await readFile(opts.reconcile, "utf8"); } catch (e) { process.stderr.write(`cannot read ${opts.reconcile}: ${e.message}\n`); return 2; }
    const b = parse1099da(bt);
    if (b.errors.length) { process.stderr.write(`--reconcile: ${b.errors[0]}\n`); return 2; }
    rec = reconcile1099da(r.result.rows, b.entries);
  }
  const plan = opts.sell ? planSale(r.result.openLots, { asset: opts.sell, price: opts.price, asOf: opts.saleDate || new Date().toISOString().slice(0, 10), qty: opts.qty ?? null, cash: opts.qty ? null : opts.cash ?? null, summary: r.result.summary, shortRate: opts.shortRate, longRate: opts.longRate }) : null;
  let pr = null;
  if (opts.prices) {
    const asOf = opts.saleDate || new Date().toISOString().slice(0, 10);
    const common = { asOf, summary: r.result.summary, shortRate: opts.shortRate, longRate: opts.longRate };
    pr = { harvest: harvestPlan(r.result.openLots, opts.prices, common), wait: waitPlan(r.result.openLots, opts.prices, common) };
  }
  const gift = opts.donate ? donationPlan(r.result.openLots, { asset: opts.donate, price: opts.price, asOf: opts.saleDate || new Date().toISOString().slice(0, 10), qty: opts.qty, longRate: opts.longRate, deductionRate: opts.deductionRate || 0 }) : null;
  if (opts.json) process.stdout.write(JSON.stringify({ ...r.result, ...(plan ? { plan } : {}), ...(pr ? { harvest: pr.harvest, wait: pr.wait } : {}), ...(gift ? { gift } : {}), ...(rec ? { reconcile: rec } : {}) }, null, 2) + "\n");
  else process.stdout.write(render(r, opts) + (plan ? renderPlan(plan) : "") + (plan && opts.idRecord ? "\n" + (idRecord(plan, opts.idRecord)?.text || "No lots to identify.\n") : "") + (pr ? renderPrices(pr.harvest, pr.wait) : "") + (gift ? renderDonation(gift) : "") + (rec ? renderReconcile(rec) : ""));
  return 0;
}

if (import.meta.url === `file://${process.argv[1]}`) process.exitCode = await main(process.argv.slice(2));

importers.mjs.text:
// Exchange-export importers. Pure functions, no I/O, no dependencies.
//
// Turns a raw export from an exchange into the plain CSV that calc.mjs reads
// (date,type,asset,quantity,total,fee,wallet), so a person can drop in the file
// they already have instead of reshaping it by hand. Nothing is priced or
// fetched: a row whose USD value the export does not carry (a coin-for-coin
// trade on Kraken, a staking reward) is written with an empty `total` and
// reported in `notes`, so it shows up as a line to fill in rather than as a
// silent zero.
//
// Formats are written from the column layouts the exchanges publish and have
// not been checked against a real account; the notes say so where it matters.

import { parseCsv, mapHeaders, normalizeType, parseDate } from "./calc.mjs";

const norm = (s) => String(s).toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
const num = (raw) => {
  const s = String(raw ?? "").replace(/[$,\s]/g, "").replace(/^\((.*)\)$/, "-$1");
  if (s === "") return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
};
const cell = (v) => (/[",\n\r]/.test(v) ? `"${String(v).replace(/"/g, '""')}"` : String(v));
const fmt = (n) => (n === null || n === undefined ? "" : String(+Number(n).toFixed(10)));

export const OUT_HEADER = "date,type,asset,quantity,total,fee,wallet";
const toCsv = (rows) => [OUT_HEADER, ...rows.map((r) => r.map(cell).join(","))].join("\n") + "\n";

// ---- format detection ----------------------------------------------------

function findHeader(grid, needles) {
  for (let i = 0; i < Math.min(grid.length, 30); i++) {
    const names = grid[i].map(norm);
    if (needles.every((n) => names.includes(n))) return i;
  }
  return -1;
}

export function detectFormat(text) {
  const grid = parseCsv(text);
  if (findHeader(grid, ["activity date", "instrument", "trans code", "quantity", "price", "amount"]) >= 0) return "robinhood";
  if (findHeader(grid, ["transaction id", "transaction type", "asset type", "asset amount", "net amount"]) >= 0) return "cashapp";
  if (findHeader(grid, ["sent amount", "sent currency", "received amount", "received currency"]) >= 0) return "koinly";
  if (findHeader(grid, ["timestamp utc", "transaction kind", "native amount in usd"]) >= 0) return "cryptocom";
  if (findHeader(grid, ["date", "time utc", "type", "symbol", "usd amount usd"]) >= 0) return "gemini";
  if (findHeader(grid, ["timestamp", "transaction type", "asset"]) >= 0) return "coinbase";
  if (findHeader(grid, ["trade id", "product", "side", "created at", "size", "price", "fee"]) >= 0) return "coinbasepro";
  if (findHeader(grid, ["txid", "refid", "time", "type", "asset", "amount", "fee"]) >= 0) return "kraken";
  if (findHeader(grid, ["time", "operation", "primary asset"]) >= 0) return "binanceus";
  if (findHeader(grid, ["date utc", "pair", "side", "price", "executed", "amount", "fee"]) >= 0) return "binance";
  if (findHeader(grid, ["type", "datetime", "account", "amount", "value", "rate", "fee", "sub type"]) >= 0) return "bitstamp";
  return "generic";
}

// ---- Coinbase ------------------------------------------------------------

const CB_BUY = ["buy", "advanced trade buy"];
const CB_SELL = ["sell", "advanced trade sell"];
const CB_INCOME = ["rewards income", "staking income", "coinbase earn", "learning reward", "inflation reward", "reward income", "airdrop"];
const CB_MOVE = ["send", "receive", "deposit", "withdrawal"];

function importCoinbase(grid) {
  const h = findHeader(grid, ["timestamp", "transaction type", "asset"]);
  const names = grid[h].map(norm);
  const col = (...opts) => { for (const o of opts) { const i = names.indexOf(o); if (i >= 0) return i; } return -1; };
  const c = {
    ts: col("timestamp"), type: col("transaction type"), asset: col("asset"),
    qty: col("quantity transacted"), cur: col("spot price currency"),
    sub: col("subtotal", "usd subtotal"), total: col("total inclusive of fees and or spread", "total inclusive of fees", "usd total inclusive of fees"),
    fee: col("fees and or spread", "usd fees", "fees"), notes: col("notes"),
  };
  const out = [], notes = [];
  let sends = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const g = (k) => (c[k] < 0 ? "" : r[c[k]] ?? "");
    const type = norm(g("type"));
    if (!type || !g("ts")) continue;
    const date = g("ts").slice(0, 10);
    const asset = g("asset").toUpperCase();
    const qty = Math.abs(num(g("qty")) ?? 0);
    const cur = g("cur").toUpperCase();
    if (cur && cur !== "USD") { notes.push(`Line ${i + 1}: priced in ${cur}, not USD, so it was skipped.`); continue; }
    const fee = Math.abs(num(g("fee")) ?? 0);
    const sub = num(g("sub"));
    const total = num(g("total"));
    // Subtotal is the value before fees; fall back to total minus fee on a buy.
    const usd = sub !== null ? Math.abs(sub) : total !== null ? Math.abs(total) : null;
    if (CB_BUY.includes(type)) out.push([date, "buy", asset, fmt(qty), fmt(usd), fmt(fee), "Coinbase"]);
    else if (CB_SELL.includes(type)) out.push([date, "sell", asset, fmt(qty), fmt(usd), fmt(fee), "Coinbase"]);
    else if (CB_INCOME.includes(type)) out.push([date, "income", asset, fmt(qty), fmt(usd), "0", "Coinbase"]);
    else if (type === "convert") {
      const m = g("notes").match(/converted\s+([\d.,]+)\s+(\S+)\s+to\s+([\d.,]+)\s+(\S+)/i);
      if (!m) { notes.push(`Line ${i + 1}: a Convert row whose Notes could not be read, so it was skipped. Enter it as a sale and a buy.`); continue; }
      const [, q1, a1, q2, a2] = m;
      out.push([date, "sell", a1.toUpperCase(), fmt(num(q1)), fmt(usd), fmt(fee), "Coinbase"]);
      out.push([date, "buy", a2.toUpperCase(), fmt(num(q2)), fmt(usd), "0", "Coinbase"]);
    } else if (CB_MOVE.includes(type)) {
      if (type === "send") sends++;
    } else notes.push(`Line ${i + 1}: unknown Coinbase type "${g("type")}", so it was skipped.`);
  }
  if (sends) notes.push(`${sends} Send row${sends > 1 ? "s" : ""} treated as transfers between your own wallets (not taxable). If any was a payment or a gift, enter it as a sale at its USD value.`);
  return { format: "coinbase", rows: out, notes };
}

// ---- Kraken (ledgers.csv) -------------------------------------------------

const OTHER_FIAT = new Set(["EUR", "GBP", "CAD", "AUD", "JPY", "CHF"]);
const STABLE = new Set(["USDT", "USDC", "DAI"]);
const ALIAS = { XBT: "BTC", XXBT: "BTC", XETH: "ETH", XXDG: "DOGE", XDG: "DOGE", XLTC: "LTC", XXRP: "XRP", XXLM: "XLM", XETC: "ETC", XXMR: "XMR", XZEC: "ZEC", ETH2: "ETH" };

export function krakenAsset(raw) {
  let a = String(raw).toUpperCase().replace(/\.(S|M|F|B|P)$/, "").replace(/\.(S|M|F|B|P)$/, "");
  if (ALIAS[a]) return ALIAS[a];
  if (a.length === 4 && a[0] === "Z" && (a === "ZUSD" || OTHER_FIAT.has(a.slice(1)))) return a.slice(1);
  return a;
}

function importKraken(grid) {
  const h = findHeader(grid, ["txid", "refid", "time", "type", "asset", "amount", "fee"]);
  const names = grid[h].map(norm);
  const ix = (n) => names.indexOf(n);
  const c = { refid: ix("refid"), time: ix("time"), type: ix("type"), sub: ix("subtype"), asset: ix("asset"), amount: ix("amount"), fee: ix("fee") };
  const out = [], notes = [];
  const trades = new Map();
  let staking = 0, fiatOther = 0, moves = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const type = norm(r[c.type] ?? "");
    const asset = krakenAsset(r[c.asset] ?? "");
    const amount = num(r[c.amount]);
    const fee = num(r[c.fee]) ?? 0;
    const date = String(r[c.time] ?? "").slice(0, 10);
    if (!type || amount === null) continue;
    if (["trade", "spend", "receive"].includes(type)) {
      const k = r[c.refid];
      if (!trades.has(k)) trades.set(k, { date, legs: [] });
      trades.get(k).legs.push({ asset, amount, fee });
    } else if (type === "staking" || (type === "earn" && norm(r[c.sub] ?? "") === "reward")) {
      staking++;
      if (amount > 0) out.push([date, "income", asset, fmt(amount - fee), "", "0", "Kraken"]);
    } else if (["deposit", "withdrawal", "transfer", "margin", "rollover", "settled", "adjustment", "earn", "sale", "dividend"].includes(type)) {
      moves++;
    } else notes.push(`Line ${i + 1}: Kraken type "${r[c.type]}" was skipped.`);
  }
  for (const { date, legs } of trades.values()) {
    const usd = legs.find((l) => l.asset === "USD");
    const crypto = legs.filter((l) => l.asset !== "USD");
    if (crypto.some((l) => OTHER_FIAT.has(l.asset))) { fiatOther++; continue; }
    if (usd && crypto.length === 1) {
      const x = crypto[0];
      const total = Math.abs(usd.amount);
      if (x.amount > 0) out.push([date, "buy", x.asset, fmt(x.amount - x.fee), fmt(total), fmt(usd.fee), "Kraken"]);
      else out.push([date, "sell", x.asset, fmt(Math.abs(x.amount) + x.fee), fmt(total), fmt(usd.fee), "Kraken"]);
    } else if (crypto.length === 2) {
      const [a, b] = crypto[0].amount < 0 ? crypto : [crypto[1], crypto[0]];
      const st = [a, b].find((l) => STABLE.has(l.asset));
      const known = st ? fmt(Math.abs(st.amount)) : ""; // a stablecoin leg is a USD figure the export does carry
      out.push([date, "sell", a.asset, fmt(Math.abs(a.amount) + a.fee), known, "0", "Kraken"]);
      out.push([date, "buy", b.asset, fmt(b.amount - b.fee), known, "0", "Kraken"]);
      if (!st) notes.push(`${date}: ${a.asset} to ${b.asset} swap has no USD value in the export. Fill in the empty total on its two rows.`);
      else notes.push(`${date}: ${a.asset} to ${b.asset} swap priced from the ${st.asset} leg at $1 per coin; check it against the day's price if the stablecoin was off its peg.`);
    } else notes.push(`${date}: a Kraken trade with ${legs.length} legs could not be read, so it was skipped.`);
  }
  if (staking) notes.push(`${staking} staking reward row${staking > 1 ? "s" : ""} imported as income with an empty USD total. Fill in each reward's USD value on the day received.`);
  if (fiatOther) notes.push(`${fiatOther} trade${fiatOther > 1 ? "s" : ""} against a non-USD currency skipped; enter them with a USD value.`);
  if (moves) notes.push(`${moves} deposit, withdrawal and transfer rows ignored as non-taxable movements.`);
  out.sort((x, y) => (x[0] < y[0] ? -1 : x[0] > y[0] ? 1 : 0));
  return { format: "kraken", rows: out, notes };
}

// ---- Binance.US (transaction history) --------------------------------------

const BN_INCOME = /reward|distribution|airdrop|referral|cashback|interest/;
const BN_MOVE = /deposit|withdraw|transfer|stake|unstake|subscri|redeem/;

function importBinanceUs(grid) {
  const h = findHeader(grid, ["time", "operation", "primary asset"]);
  const names = grid[h].map(norm);
  const ix = (n) => names.indexOf(n);
  const c = {
    time: ix("time"), cat: ix("category"), op: ix("operation"), asset: ix("primary asset"),
    qty: ix("realized amount for primary asset"), usd: ix("realized amount for primary asset in usd value"),
    qusd: ix("realized amount for quote asset in usd value"), fusd: ix("realized amount for fee asset in usd value"),
  };
  const out = [], notes = [];
  let moves = 0, unpriced = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const g = (k) => (c[k] < 0 ? "" : r[c[k]] ?? "");
    const op = norm(g("op"));
    if (!op || !g("time")) continue;
    const date = g("time").slice(0, 10);
    const asset = g("asset").toUpperCase();
    const qty = Math.abs(num(g("qty")) ?? 0);
    const usd = num(g("usd")) ?? num(g("qusd"));
    const total = usd === null ? null : Math.abs(usd);
    const fee = Math.abs(num(g("fusd")) ?? 0);
    if (/^buy\b/.test(op) || /^sell\b/.test(op)) {
      if (total === null) unpriced++;
      out.push([date, op.startsWith("buy") ? "buy" : "sell", asset, fmt(qty), fmt(total), fmt(fee), "Binance.US"]);
    } else if (BN_INCOME.test(op) || BN_INCOME.test(norm(g("cat")))) {
      if (total === null) unpriced++;
      out.push([date, "income", asset, fmt(qty), fmt(total), "0", "Binance.US"]);
    } else if (BN_MOVE.test(op)) moves++;
    else notes.push(`Line ${i + 1}: Binance.US operation "${g("op")}" was skipped.`);
  }
  if (unpriced) notes.push(`${unpriced} Binance.US row${unpriced > 1 ? "s" : ""} had no USD value in the export and were left with an empty total. Fill each in from that day's price.`);
  if (moves) notes.push(`${moves} deposit, withdrawal and staking-transfer rows ignored as non-taxable movements.`);
  return { format: "binanceus", rows: out, notes };
}

// ---- Crypto.com App (transaction history) ----------------------------------

const CDC_BUY = /purchase|buy/;
const CDC_SELL = /viban_exchange|sell|crypto_to_fiat/;
const CDC_SWAP = /crypto_exchange|dust_conversion|swap|convert/;
const CDC_INCOME = /reward|interest|cashback|referral|airdrop|rebate|bonus/;
const CDC_MOVE = /deposit|withdraw|transfer|lockup|stake|lock|card_top_up|admin/;

function importCryptoCom(grid) {
  const h = findHeader(grid, ["timestamp utc", "transaction kind", "native amount in usd"]);
  const names = grid[h].map(norm);
  const ix = (n) => names.indexOf(n);
  const c = {
    ts: ix("timestamp utc"), cur: ix("currency"), amt: ix("amount"), toCur: ix("to currency"), toAmt: ix("to amount"),
    usd: ix("native amount in usd"), kind: ix("transaction kind"),
  };
  const out = [], notes = [];
  let moves = 0, unpriced = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const g = (k) => (c[k] < 0 ? "" : r[c[k]] ?? "");
    const kind = String(g("kind")).toLowerCase().trim();
    if (!kind || !g("ts")) continue;
    const date = g("ts").slice(0, 10);
    const cur = g("cur").toUpperCase();
    const qty = Math.abs(num(g("amt")) ?? 0);
    const usd = num(g("usd"));
    const total = usd === null ? null : Math.abs(usd);
    const row = (type, asset, q) => {
      if (total === null) unpriced++;
      out.push([date, type, asset, fmt(q), fmt(total), "0", "Crypto.com"]);
    };
    if (CDC_SELL.test(kind)) row("sell", cur, qty);
    else if (CDC_BUY.test(kind)) row("buy", cur, qty);
    else if (CDC_SWAP.test(kind) && g("toCur")) {
      row("sell", cur, qty);
      row("buy", g("toCur").toUpperCase(), Math.abs(num(g("toAmt")) ?? 0));
    } else if (CDC_INCOME.test(kind) && (num(g("amt")) ?? 0) > 0) row("income", cur, qty);
    else if (CDC_MOVE.test(kind)) moves++;
    else notes.push(`Line ${i + 1}: Crypto.com transaction kind "${g("kind")}" was skipped.`);
  }
  if (unpriced) notes.push(`${unpriced} Crypto.com row${unpriced > 1 ? "s" : ""} had no USD value in the export and were left with an empty total. Fill each in from that day's price.`);
  if (moves) notes.push(`${moves} deposit, withdrawal, transfer and staking-lock rows ignored as non-taxable movements. A withdrawal that paid someone is a sale; enter it by hand.`);
  notes.push("The export has no fee column, so fees are 0; the Native Amount (in USD) on App trades already includes the spread.");
  out.sort((x, y) => (x[0] < y[0] ? -1 : x[0] > y[0] ? 1 : 0));
  return { format: "cryptocom", rows: out, notes };
}

// ---- Gemini (transaction history) -----------------------------------------

const GEM_INCOME = /interest|reward|earn|staking|airdrop|bonus|rebate/;
const GEM_MOVE = /credit|debit|deposit|withdraw|transfer/;
// Gemini writes amounts as "$1,000.00", "(100.00)" or "0.01 BTC".
const gemNum = (raw) => num(String(raw ?? "").replace(/[A-Za-z]+/g, ""));

function importGemini(grid) {
  const h = findHeader(grid, ["date", "time utc", "type", "symbol", "usd amount usd"]);
  const names = grid[h].map(norm);
  const ix = (n) => names.indexOf(n);
  const c = { date: ix("date"), type: ix("type"), sym: ix("symbol"), usd: ix("usd amount usd"), fee: ix("trading fee usd usd") };
  const out = [], notes = [];
  let moves = 0, unpriced = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const g = (k) => (c[k] < 0 ? "" : r[c[k]] ?? "");
    const type = norm(g("type"));
    if (!type || !g("date")) continue;
    const date = g("date").slice(0, 10);
    const sym = g("sym").toUpperCase().trim();
    if (type === "buy" || type === "sell") {
      const base = sym.endsWith("USD") ? sym.slice(0, -3) : "";
      const qcol = base ? ix(`${base.toLowerCase()} amount ${base.toLowerCase()}`) : -1;
      const qty = qcol < 0 ? null : Math.abs(gemNum(r[qcol]) ?? 0);
      if (!base || qty === null) {
        notes.push(`Line ${i + 1}: Gemini ${type} of "${g("sym")}" was skipped (only USD pairs with a matching amount column are read).`);
        continue;
      }
      const usd = gemNum(g("usd"));
      const total = usd === null ? null : Math.abs(usd);
      if (total === null) unpriced++;
      out.push([date, type, base, fmt(qty), fmt(total), fmt(Math.abs(gemNum(g("fee")) ?? 0)), "Gemini"]);
    } else if (GEM_INCOME.test(type)) {
      const col = ix(`${sym.toLowerCase()} amount ${sym.toLowerCase()}`);
      const qty = col < 0 ? null : Math.abs(gemNum(r[col]) ?? 0);
      if (!sym || qty === null) { notes.push(`Line ${i + 1}: Gemini "${g("type")}" for "${g("sym")}" was skipped.`); continue; }
      unpriced++;
      out.push([date, "income", sym, fmt(qty), "", "0", "Gemini"]);
    } else if (GEM_MOVE.test(type)) moves++;
    else notes.push(`Line ${i + 1}: Gemini transaction type "${g("type")}" was skipped.`);
  }
  if (unpriced) notes.push(`${unpriced} Gemini row${unpriced > 1 ? "s" : ""} had no USD value in the export and were left with an empty total. Fill each in from that day's price.`);
  if (moves) notes.push(`${moves} credit, debit, deposit and withdrawal rows ignored as non-taxable movements. A withdrawal that paid someone is a sale; enter it by hand.`);
  return { format: "gemini", rows: out, notes };
}

// ---- Bitstamp ------------------------------------------------------------
//
// Bitstamp's transaction export is one row per trade with the amounts spelled
// as "0.5 BTC" / "10000 USD" and a date such as "Jan. 10, 2023, 10:00 AM".
// Only USD-valued Market buys and sells are read; a trade valued in another
// currency is skipped with a note rather than converted at a rate nobody typed.

const MONTHS = { jan: "01", feb: "02", mar: "03", apr: "04", may: "05", jun: "06", jul: "07", aug: "08", sep: "09", oct: "10", nov: "11", dec: "12" };
function bitstampDate(raw) {
  const s = String(raw ?? "").trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return s.slice(0, 10);
  const m = s.match(/^([A-Za-z]{3})[a-z]*\.?\s+(\d{1,2}),\s*(\d{4})/);
  return m && MONTHS[m[1].toLowerCase()] ? `${m[3]}-${MONTHS[m[1].toLowerCase()]}-${m[2].padStart(2, "0")}` : "";
}
// "0.5 BTC" -> { n: 0.5, cur: "BTC" }
const bitstampAmount = (raw) => {
  const m = String(raw ?? "").trim().match(/^(.*?)\s*([A-Za-z]{2,10})$/);
  return m ? { n: num(m[1]), cur: m[2].toUpperCase() } : { n: num(raw), cur: "" };
};

function importBitstamp(grid) {
  const h = findHeader(grid, ["type", "datetime", "account", "amount", "value", "rate", "fee", "sub type"]);
  const names = grid[h].map(norm);
  const c = { type: names.indexOf("type"), date: names.indexOf("datetime"), amount: names.indexOf("amount"), value: names.indexOf("value"), fee: names.indexOf("fee"), sub: names.indexOf("sub type") };
  const out = [], notes = [];
  let moves = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const type = norm(r[c.type] ?? "");
    if (!type) continue;
    if (type !== "market") {
      if (/deposit|withdrawal|sub account transfer/.test(type)) moves++;
      else notes.push(`Line ${i + 1}: Bitstamp row type "${r[c.type]}" was skipped.`);
      continue;
    }
    const side = norm(r[c.sub] ?? "");
    const date = bitstampDate(r[c.date]);
    const amt = bitstampAmount(r[c.amount]);
    const val = bitstampAmount(r[c.value]);
    const fee = bitstampAmount(r[c.fee]);
    if ((side !== "buy" && side !== "sell") || !date || amt.n === null || !amt.cur) {
      notes.push(`Line ${i + 1}: Bitstamp ${side || "trade"} could not be read and was skipped.`);
      continue;
    }
    if (val.cur !== "USD") {
      notes.push(`Line ${i + 1}: Bitstamp ${side} of ${amt.cur} is valued in ${val.cur || "an unknown currency"}, not USD, and was skipped. Enter it by hand at that day's USD value.`);
      continue;
    }
    out.push([date, side, amt.cur, fmt(Math.abs(amt.n)), fmt(val.n === null ? null : Math.abs(val.n)), fmt(fee.cur === "USD" && fee.n !== null ? Math.abs(fee.n) : 0), "Bitstamp"]);
    if (fee.n && fee.cur !== "USD") notes.push(`Line ${i + 1}: Bitstamp fee in ${fee.cur || "another currency"} was not counted; add it to the fee by hand.`);
  }
  if (moves) notes.push(`${moves} deposit and withdrawal rows ignored as non-taxable movements. A withdrawal that paid someone is a sale; enter it by hand.`);
  return { format: "bitstamp", rows: out, notes };
}

// ---- Coinbase Pro / Advanced Trade fills ----------------------------------

// The fills report is one row per fill: `product` is BASE-QUOTE (BTC-USD), `size`
// is in base coins, `price` is per coin in the quote currency and `fee` is in the
// quote currency. Only USD-quoted products are read; a coin-for-coin or
// stablecoin-quoted fill is skipped with a note rather than priced at a rate
// nobody typed.

function importCoinbasePro(grid) {
  const h = findHeader(grid, ["trade id", "product", "side", "created at", "size", "price", "fee"]);
  const names = grid[h].map(norm);
  const c = Object.fromEntries(["product", "side", "created at", "size", "price", "fee"].map((k) => [k, names.indexOf(k)]));
  const out = [], notes = [];
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const product = String(r[c.product] ?? "").trim().toUpperCase();
    if (!product) continue;
    const side = norm(r[c.side] ?? "");
    const date = String(r[c["created at"]] ?? "").slice(0, 10);
    const qty = num(r[c.size]), price = num(r[c.price]), fee = num(r[c.fee]);
    const [base, quote] = product.split("-");
    if ((side !== "buy" && side !== "sell") || !/^\d{4}-\d{2}-\d{2}$/.test(date) || qty === null || price === null || !base) {
      notes.push(`Line ${i + 1}: a Coinbase fill could not be read and was skipped.`);
      continue;
    }
    if (quote !== "USD") {
      notes.push(`Line ${i + 1}: ${product} ${side} is quoted in ${quote || "an unknown currency"}, not USD, and was skipped. Enter it by hand as a sale and a buy at that day's USD value.`);
      continue;
    }
    out.push([date, side, base, fmt(Math.abs(qty)), fmt(Math.abs(qty * price)), fmt(fee === null ? 0 : Math.abs(fee)), "Coinbase"]);
  }
  return { format: "coinbasepro", rows: out, notes };
}

// ---- Koinly universal format ---------------------------------------------
//
// Koinly's "universal" CSV (also what several other tax tools accept) has one
// row per movement: Sent and Received amount/currency, an optional fee and a
// Net Worth value, plus a Label. Reading it lets someone who exported their
// history from a paid service run the five-method comparison on it locally.
// Only USD values are used; the Net Worth figure is Koinly's own estimate of
// the value of the movement, taken as given.

const KL_INCOME = /reward|staking|mining|airdrop|income|interest|cashback|fork|lending|liquidity/;
const KL_FIAT = new Set(["USD", "EUR", "GBP", "CAD", "AUD", "JPY", "CHF", "NZD", "SEK", "NOK", "DKK", "PLN", "INR", "BRL", "MXN", "SGD", "HKD"]);

function importKoinly(grid) {
  const h = findHeader(grid, ["sent amount", "sent currency", "received amount", "received currency"]);
  const names = grid[h].map(norm);
  const ix = (n) => names.indexOf(n);
  const c = {
    date: ix("date"), sa: ix("sent amount"), sc: ix("sent currency"), ra: ix("received amount"), rc: ix("received currency"),
    fa: ix("fee amount"), fc: ix("fee currency"), nw: ix("net worth amount"), nc: ix("net worth currency"), label: ix("label"),
  };
  const out = [], notes = [];
  let moves = 0, unpriced = 0, otherFiat = 0, feeSkipped = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const g = (k) => (c[k] < 0 ? "" : r[c[k]] ?? "");
    if (!g("date")) continue;
    const date = g("date").trim().slice(0, 10);
    const sent = Math.abs(num(g("sa")) ?? 0), recv = Math.abs(num(g("ra")) ?? 0);
    const sc = g("sc").toUpperCase().trim(), rc = g("rc").toUpperCase().trim();
    const label = String(g("label")).toLowerCase().trim();
    const nwUsd = g("nc").toUpperCase().trim() === "USD" ? num(g("nw")) : null;
    let fee = 0;
    if (num(g("fa"))) {
      if (g("fc").toUpperCase().trim() === "USD") fee = Math.abs(num(g("fa")));
      else feeSkipped++;
    }
    if ((sent && KL_FIAT.has(sc) && sc !== "USD") || (recv && KL_FIAT.has(rc) && rc !== "USD")) { otherFiat++; continue; }
    const sentCoin = sent && sc && !KL_FIAT.has(sc), recvCoin = recv && rc && !KL_FIAT.has(rc);
    const sentUsd = sent && sc === "USD", recvUsd = recv && rc === "USD";
    if (recvCoin && sentUsd) out.push([date, "buy", rc, fmt(recv), fmt(sent), fmt(fee), "Koinly"]);
    else if (sentCoin && recvUsd) out.push([date, "sell", sc, fmt(sent), fmt(recv), fmt(fee), "Koinly"]);
    else if (sentCoin && recvCoin) {
      if (nwUsd === null) unpriced++;
      const total = nwUsd === null ? null : Math.abs(nwUsd);
      out.push([date, "sell", sc, fmt(sent), fmt(total), fmt(fee), "Koinly"]);
      out.push([date, "buy", rc, fmt(recv), fmt(total), "0", "Koinly"]);
    } else if (recvCoin && !sent && KL_INCOME.test(label)) {
      if (nwUsd === null) unpriced++;
      out.push([date, "income", rc, fmt(recv), fmt(nwUsd === null ? null : Math.abs(nwUsd)), "0", "Koinly"]);
    } else if (sentCoin && !recv && /gift|donation|payment|cost/.test(label)) {
      if (nwUsd === null) unpriced++;
      out.push([date, "sell", sc, fmt(sent), fmt(nwUsd === null ? null : Math.abs(nwUsd)), fmt(fee), "Koinly"]);
    } else moves++;
  }
  if (unpriced) notes.push(`${unpriced} Koinly row${unpriced > 1 ? "s" : ""} had no USD Net Worth value and were left with an empty total. Fill each in from that day's price.`);
  if (moves) notes.push(`${moves} unlabelled deposit, withdrawal and transfer rows ignored as movements between your own wallets. A withdrawal that paid someone is a sale; enter it by hand.`);
  if (otherFiat) notes.push(`${otherFiat} row${otherFiat > 1 ? "s" : ""} paid in a non-USD currency were skipped, not converted at a rate nobody typed.`);
  if (feeSkipped) notes.push(`${feeSkipped} fee${feeSkipped > 1 ? "s" : ""} paid in a coin or non-USD currency were left out.`);
  notes.push("Koinly's own cost-basis method and Net Worth estimates are not carried over; the figures here come from the amounts in the file.");
  return { format: "koinly", rows: out, notes };
}

// ---- Cash App ------------------------------------------------------------
//
// Cash App's account-activity export has one row per transaction with the
// asset in `Asset Type`, the coin quantity in `Asset Amount` and the dollars in
// `Amount` ("-$10,000.00" on a buy) and `Fee`. Only Bitcoin Buy / Sale rows
// are taxable trades here; Boost, bonus and reward rows are income at no
// recorded value; sends, receives and plain cash movements are ignored.

const CA_INCOME = /boost|bonus|reward|bitcoin rewards|round up|giveaway|referral/;
const CA_MOVE = /deposit|withdraw|cash out|add cash|p2p|payment|card|send|receive|transfer|paycheck/;

function importCashApp(grid) {
  const h = findHeader(grid, ["transaction id", "transaction type", "asset type", "asset amount", "net amount"]);
  const names = grid[h].map(norm);
  const ix = (n) => names.indexOf(n);
  const c = { date: ix("date"), type: ix("transaction type"), amt: ix("amount"), fee: ix("fee"), asset: ix("asset type"), qty: ix("asset amount"), status: ix("status") };
  const out = [], notes = [];
  let moves = 0, unpriced = 0, failed = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const g = (k) => (c[k] < 0 ? "" : r[c[k]] ?? "");
    const type = norm(g("type"));
    if (!type || !g("date")) continue;
    const status = norm(g("status"));
    if (status && status !== "complete" && status !== "completed") { failed++; continue; }
    const date = g("date").slice(0, 10);
    const asset = g("asset").toUpperCase().trim();
    const qty = num(g("qty"));
    const isBuy = /\bbuy\b|\bpurchase\b/.test(type) && asset, isSell = /\bsale\b|\bsell\b/.test(type) && asset;
    if (isBuy || isSell) {
      if (qty === null || qty === 0) { notes.push(`Line ${i + 1}: Cash App ${g("type")} had no Asset Amount and was skipped.`); continue; }
      const usd = num(g("amt"));
      if (usd === null) unpriced++;
      out.push([date, isBuy ? "buy" : "sell", asset, fmt(Math.abs(qty)), fmt(usd === null ? null : Math.abs(usd)), fmt(Math.abs(num(g("fee")) ?? 0)), "Cash App"]);
    } else if (asset && qty && CA_INCOME.test(type)) {
      unpriced++;
      out.push([date, "income", asset, fmt(Math.abs(qty)), "", "0", "Cash App"]);
    } else if (CA_MOVE.test(type) || !asset) moves++;
    else notes.push(`Line ${i + 1}: Cash App transaction type "${g("type")}" was skipped.`);
  }
  if (unpriced) notes.push(`${unpriced} Cash App row${unpriced > 1 ? "s" : ""} had no USD value in the export and were left with an empty total. Fill each in from that day's price.`);
  if (failed) notes.push(`${failed} Cash App row${failed > 1 ? "s" : ""} with a status other than complete (failed, pending, cancelled) ignored.`);
  if (moves) notes.push(`${moves} deposit, withdrawal, payment and cash rows ignored as non-taxable movements. Sending bitcoin to someone as payment is a sale; enter it by hand.`);
  notes.push("Cash App: the export's Amount is read as the dollars traded and Fee as separate; check one row against the app before relying on the basis.");
  return { format: "cashapp", rows: out, notes };
}

// ---- Robinhood (account activity report) ------------------------------------
//
// Columns: Activity Date, Instrument, Description, Trans Code, Quantity, Price,
// Amount (buys in parentheses). The report mixes stocks and options with crypto,
// so only rows whose Instrument is a coin ticker listed below are read; every
// other instrument is counted and ignored. Buy and Sell codes become trades;
// the dollars come from Amount (what actually moved), not Quantity x Price.

const RH_COINS = new Set(["BTC", "ETH", "DOGE", "SOL", "LTC", "BCH", "ETC", "XRP", "ADA", "AVAX", "LINK", "XLM", "UNI", "SHIB", "MATIC", "POL", "AAVE", "COMP", "XTZ", "USDC", "DOT", "ATOM", "HBAR", "PEPE", "ARB", "SUI", "TON", "NEAR", "APT"]);

function importRobinhood(grid) {
  const h = findHeader(grid, ["activity date", "instrument", "trans code", "quantity", "price", "amount"]);
  const names = grid[h].map(norm);
  const ix = (n) => names.indexOf(n);
  const c = { date: ix("activity date"), sym: ix("instrument"), code: ix("trans code"), qty: ix("quantity"), price: ix("price"), amt: ix("amount") };
  const out = [], notes = [];
  let other = 0, unpriced = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const g = (k) => r[c[k]] ?? "";
    const sym = g("sym").toUpperCase().trim();
    const code = norm(g("code"));
    if (!sym || !code) continue;
    if (!RH_COINS.has(sym)) { other++; continue; }
    const date = parseDate(g("date"));
    const qty = num(g("qty"));
    if (code === "buy" || code === "sell") {
      if (!date || qty === null || qty === 0) { notes.push(`Line ${i + 1}: Robinhood ${g("code")} of ${sym} had no usable date or quantity and was skipped.`); continue; }
      let usd = num(g("amt"));
      if (usd === null) {
        const price = num(g("price"));
        usd = price === null ? null : price * Math.abs(qty);
        if (usd === null) unpriced++;
      }
      out.push([date, code, sym, fmt(Math.abs(qty)), fmt(usd === null ? null : Math.abs(usd)), "0", "Robinhood"]);
    } else notes.push(`Line ${i + 1}: Robinhood transaction code "${g("code")}" for ${sym} was skipped; enter it by hand if it is taxable.`);
  }
  if (unpriced) notes.push(`${unpriced} Robinhood row${unpriced > 1 ? "s" : ""} had no USD value and were left with an empty total. Fill each in from that day's price.`);
  if (other) notes.push(`${other} row${other > 1 ? "s" : ""} for stocks, options, cash or coins not on the reader's list ignored.`);
  notes.push("Robinhood: any spread is already inside the price, so fees are read as 0. Check one row against the app, and skim the file for coins missing from the list, before relying on the basis.");
  return { format: "robinhood", rows: out, notes };
}

// ---- Binance (global spot trade history) -------------------------------------
//
// Columns: Date(UTC), Pair, Side, Price, Executed, Amount, Fee. Executed, Amount
// and Fee carry the coin as a suffix ("0.5BTC", "30000USDT"). A pair quoted in a
// dollar stablecoin is priced 1:1 with USD (disclosed in the notes); a pair
// quoted in another coin is a coin-for-coin swap, written as a sale of one and a
// purchase of the other with the total left empty, as for Kraken. A fee paid in
// BNB or any coin that is neither side of the pair is left at 0 and counted.

const BN_USD = new Set(["USD", "USDT", "USDC", "BUSD", "FDUSD", "TUSD", "USDP", "DAI"]);
const BN_QUOTES = ["FDUSD", "USDT", "USDC", "BUSD", "TUSD", "USDP", "DAI", "USD", "BTC", "ETH", "BNB", "EUR", "GBP", "TRY", "BRL", "AUD", "JPY"];
const bnSplit = (raw) => {
  const m = String(raw ?? "").replace(/,/g, "").trim().match(/^(-?[0-9]*\.?[0-9]+(?:e[+-]?[0-9]+)?)\s*([A-Za-z0-9]+)$/i);
  return m ? { n: Number(m[1]), coin: m[2].toUpperCase() } : null;
};

function importBinance(grid) {
  const h = findHeader(grid, ["date utc", "pair", "side", "price", "executed", "amount", "fee"]);
  const names = grid[h].map(norm);
  const ix = (n) => names.indexOf(n);
  const c = { date: ix("date utc"), pair: ix("pair"), side: ix("side"), exec: ix("executed"), amt: ix("amount"), fee: ix("fee") };
  const out = [], notes = [];
  let stable = 0, swaps = 0, feeLeft = 0, fiat = 0;
  for (let i = h + 1; i < grid.length; i++) {
    const r = grid[i];
    const g = (k) => r[c[k]] ?? "";
    if (!g("pair") || !g("date")) continue;
    const side = norm(g("side"));
    const date = parseDate(g("date"));
    const exec = bnSplit(g("exec")), amt = bnSplit(g("amt"));
    const pair = g("pair").toUpperCase().replace(/[^A-Z0-9]/g, "");
    const quote = BN_QUOTES.find((q) => pair.endsWith(q) && pair.length > q.length);
    const base = quote ? pair.slice(0, -quote.length) : "";
    if (!date || !exec || !amt || (side !== "buy" && side !== "sell") || !quote || exec.coin !== base || amt.coin !== quote) {
      notes.push(`Line ${i + 1}: Binance row for "${g("pair")}" could not be read and was skipped.`);
      continue;
    }
    const qty = Math.abs(exec.n), cost = Math.abs(amt.n);
    const fee = bnSplit(g("fee"));
    let feeUsd = 0;
    if (fee && fee.n) {
      if (BN_USD.has(fee.coin) && BN_USD.has(quote)) feeUsd = Math.abs(fee.n);
      else if (fee.coin === base && BN_USD.has(quote)) feeUsd = Math.abs(fee.n) * (qty ? cost / qty : 0);
      else if (fee.coin === quote && BN_USD.has(quote)) feeUsd = Math.abs(fee.n);
      else feeLeft++;
    }
    if (BN_USD.has(quote)) {
      stable++;
      out.push([date, side, base, fmt(qty), fmt(cost), fmt(feeUsd), "Binance"]);
    } else if (["EUR", "GBP", "TRY", "BRL", "AUD", "JPY"].includes(quote)) {
      fiat++;
      out.push([date, side, base, fmt(qty), "", "0", "Binance"]);
    } else {
      swaps++;
      out.push([date, side, base, fmt(qty), "", "0", "Binance"]);
      out.push([date, side === "buy" ? "sell" : "buy", quote, fmt(cost), "", "0", "Binance"]);
    }
  }
  if (stable) notes.push(`${stable} Binance row${stable > 1 ? "s" : ""} quoted in a dollar stablecoin (USDT, USDC, BUSD and similar) were priced at $1 per coin. A stablecoin that traded off its peg will be slightly off; check the dates that matter.`);
  if (swaps) notes.push(`${swaps} Binance coin-for-coin trade${swaps > 1 ? "s" : ""} became a sale and a purchase with an empty total. Fill each in with the USD value that day.`);
  if (fiat) notes.push(`${fiat} Binance row${fiat > 1 ? "s" : ""} quoted in a non-USD currency left with an empty total. Fill each in with the USD value that day.`);
  if (feeLeft) notes.push(`${feeLeft} Binance row${feeLeft > 1 ? "s" : ""} paid a fee in BNB or another coin; the fee was left at 0 because the export carries no USD value for it.`);
  notes.push("Binance: written from the published column layout, not checked against a real account. Binance.com is not open to US residents; the tool estimates US-style gains.");
  return { format: "binance", rows: out, notes };
}

// ---- entry points ---------------------------------------------------------

export const FORMAT_LABELS = { coinbase: "Coinbase transaction history", coinbasepro: "Coinbase Pro / Advanced Trade fills", kraken: "Kraken ledger", binanceus: "Binance.US transaction history", binance: "Binance spot trade history", koinly: "Koinly universal CSV", cryptocom: "Crypto.com App transaction history", gemini: "Gemini transaction history", bitstamp: "Bitstamp transaction export", cashapp: "Cash App account activity", robinhood: "Robinhood account activity", generic: "plain CSV" };

// Returns { format, csv, notes }. A generic file comes back unchanged.
export function convertExchangeCsv(text) {
  const format = detectFormat(text);
  if (format === "generic") return { format, csv: String(text ?? ""), notes: [] };
  const grid = parseCsv(text);
  const r = format === "coinbase" ? importCoinbase(grid) : format === "coinbasepro" ? importCoinbasePro(grid) : format === "binanceus" ? importBinanceUs(grid) : format === "binance" ? importBinance(grid) : format === "koinly" ? importKoinly(grid) : format === "cryptocom" ? importCryptoCom(grid) : format === "gemini" ? importGemini(grid) : format === "bitstamp" ? importBitstamp(grid) : format === "cashapp" ? importCashApp(grid) : format === "robinhood" ? importRobinhood(grid) : importKraken(grid);
  return { format, csv: toCsv(r.rows), notes: r.notes, count: r.rows.length };
}

// Several files at once (e.g. two exchanges, or one per year): one CSV, one header.
export function convertMany(files) {
  const lines = [], notes = [], formats = [];
  for (const f of files) {
    const r = convertExchangeCsv(f.text);
    formats.push(r.format);
    for (const n of r.notes) notes.push(files.length > 1 ? `${f.name}: ${n}` : n);
    const body = r.csv.split(/\r?\n/);
    if (lines.length === 0) lines.push(...body.filter((l) => l.trim()));
    else {
      if (r.format === "generic" && norm(body[0]) !== norm(OUT_HEADER)) notes.push(`${f.name}: header differs from the first file's; check that the columns line up.`);
      lines.push(...body.slice(1).filter((l) => l.trim()));
    }
  }
  return { formats, csv: lines.join("\n") + "\n", notes };
}

// ---- map your own columns -------------------------------------------------
//
// For an export none of the readers above recognise (a broker, a wallet app,
// a spreadsheet of your own): the person says which column is which and what
// each value in the type column means, and this writes the same plain CSV.
// No exchange layout is assumed, so nothing here can be wrong about one.

export const MAP_FIELDS = ["date", "type", "asset", "quantity", "total", "price", "fee", "wallet"];
export const MAP_KINDS = ["buy", "sell", "income", "transfer", "skip"];

// Guess a mapping from the first row that has a date and a quantity column.
// Returns { headers, cols, typeValues, typeMap } or null when there is no
// header row to work from. typeCol overrides the guessed type column. typeMap holds only the guesses calc.mjs already knows.
export function suggestMapping(text, typeCol) {
  const grid = parseCsv(text);
  if (grid.length < 2) return null;
  const headers = grid[0];
  const cols = mapHeaders(headers);
  if (typeCol !== undefined) cols.type = typeCol;
  const typeValues = [];
  if (cols.type !== undefined) {
    const seen = new Set();
    for (const r of grid.slice(1)) { const v = (r[cols.type] ?? "").trim(); if (v && !seen.has(v)) { seen.add(v); typeValues.push(v); } }
  }
  const typeMap = {};
  for (const v of typeValues) typeMap[v] = (n => (n === "swap" ? "skip" : n))(normalizeType(v)) ?? "skip"; // the mapper has no second-coin column, so a swap-like word stays for the user to decide
  return { headers, cols, typeValues, typeMap };
}

// mapping: { cols: { field: columnIndex }, typeMap: { rawValue: kind }, asset?: "BTC" }.
// A fixed `asset` is for a single-coin file with no asset column. Amounts are
// read as magnitudes (a sale exported as a negative quantity still sells); a
// missing total is price times quantity. Rows that cannot be read are listed in
// notes with their line number, never written as zero.
export function applyMapping(text, mapping) {
  const grid = parseCsv(text);
  const { cols = {}, typeMap = {} } = mapping || {};
  const notes = [];
  const rows = [];
  const need = ["date", "type", "quantity"].filter((f) => cols[f] === undefined);
  if (cols.asset === undefined && !mapping?.asset) need.push("asset");
  if (cols.total === undefined && cols.price === undefined) need.push("total or price");
  if (need.length) return { csv: toCsv([]), rows, notes: [`Pick a column for: ${need.join(", ")}.`] };
  const typeKey = new Map(Object.entries(typeMap).map(([k, v]) => [norm(k), v]));
  const at = (r, f) => (cols[f] === undefined ? "" : (r[cols[f]] ?? ""));
  let skipped = 0;
  for (let i = 1; i < grid.length; i++) {
    const r = grid[i], line = i + 1;
    const kind = typeKey.get(norm(at(r, "type")));
    if (kind === undefined) { notes.push(`Line ${line}: type "${at(r, "type")}" has no meaning assigned, row left out.`); continue; }
    if (kind === "skip") { skipped++; continue; }
    const date = parseDate(at(r, "date"));
    const qty = num(at(r, "quantity"));
    const asset = (mapping.asset || at(r, "asset")).trim().toUpperCase();
    if (!date || qty === null || qty === 0 || !asset) { notes.push(`Line ${line}: date, asset or quantity could not be read, row left out.`); continue; }
    const q = Math.abs(qty);
    let total = num(at(r, "total"));
    if (total === null) { const p = num(at(r, "price")); if (p !== null) total = p * q; }
    if (total === null && kind !== "transfer") notes.push(`Line ${line}: no USD value, left empty for you to fill in.`);
    const fee = num(at(r, "fee"));
    rows.push([date, kind, asset, fmt(q), fmt(total === null ? null : Math.abs(total)), fmt(fee === null ? null : Math.abs(fee)), at(r, "wallet")]);
  }
  if (skipped) notes.push(`${skipped} row${skipped > 1 ? "s" : ""} marked "skip" left out.`);
  return { csv: toCsv(rows), rows, notes };
}

